INSERT INTO livros
    (id, titulo, autor, categoria, volume, editora, titulo_original, descricao, capa_editorial, fonte, isbn, generos)
VALUES
    ('INK-0001', 'One Piece', 'Eiichiro Oda', 'Mangá', 'Vol. 1', 'VIZ Media', NULL, 'A infância de Monkey D. Luffy ganha outro rumo quando ele conhece o pirata Shanks e come uma fruta que dá elasticidade ao seu corpo. O poder cobra um preço curioso para quem sonha viver no mar: Luffy perde a capacidade de nadar. Anos depois, parte sozinho em busca do One Piece. Antes de encontrar o tesouro, precisa reunir uma tripulação e decidir por quem vale a pena arriscar a própria liberdade. Edição em inglês, 216 páginas.', 'https://d28hgpri8am2if.cloudfront.net/book_images/cvr9781569319017_9781569319017_hr.jpg', 'https://www.simonandschuster.com/books/One-Piece-Vol-1/Eiichiro-Oda/One-Piece/9781569319017', '9781569319017', 'Ação e aventura|Fantasia'),
    ('INK-0002', 'Naruto', 'Masashi Kishimoto', 'Mangá', 'Vol. 1', 'VIZ Media', NULL, 'Naruto Uzumaki vive na Vila da Folha e sonha tornar-se Hokage, o líder dos ninjas. Na academia, suas travessuras chamam mais atenção do que sua técnica. Às vésperas da graduação, um pergaminho proibido e a intervenção de seu professor Iruka colocam em jogo a confiança que Naruto tanto deseja conquistar. O primeiro volume acompanha a passagem desse aluno solitário para uma equipe em que talento individual e cooperação terão de conviver. Edição em inglês, 192 páginas.', 'https://d28hgpri8am2if.cloudfront.net/book_images/cvr9781569319000_9781569319000_hr.jpg', 'https://www.simonandschuster.com/books/Naruto-Vol-1/Masashi-Kishimoto/Naruto/9781569319000', '9781569319000', 'Ação e aventura|Fantasia'),
    ('INK-0003', 'Batman: Year One', 'Frank Miller e David Mazzucchelli', 'HQ', 'Edição encadernada', 'DC Comics', NULL, 'Bruce Wayne retorna a Gotham enquanto o tenente James Gordon chega à cidade para assumir um posto na polícia. Os dois descobrem a mesma rede de corrupção de lados diferentes. A narrativa alterna seus pontos de vista ao longo do primeiro ano de atividade de Batman. Edição em inglês que reúne os quatro capítulos da história.', 'https://images.penguinrandomhouse.com/cover/9781401207526', 'https://www.penguinrandomhouse.com/books/114571/batman-year-one-by-frank-miller-david-mazzucchelli/', '9781401207526', 'Super-heróis|Mistério e suspense'),
    ('INK-0004', 'Dragon Ball', 'Akira Toriyama', 'Mangá', 'Vol. 1', 'VIZ Media', NULL, 'Goku cresceu longe das cidades, tem força extraordinária e guarda uma esfera deixada pelo avô. Bulma, uma inventora que rastreia artefatos com um radar, reconhece nela uma das sete Esferas do Dragão. Reunidas, elas permitem invocar um dragão capaz de conceder um desejo. Os dois partem juntos por motivos diferentes, numa viagem em que engenhocas, artes marciais e humor põem à prova a ingenuidade de Goku e os planos de Bulma. Edição em inglês, 192 páginas.', 'https://d28hgpri8am2if.cloudfront.net/book_images/onix/cvr9781569319208/dragon-ball-vol-1-9781569319208_hr.jpg', 'https://www.simonandschuster.com/books/Dragon-Ball-Vol-1/Akira-Toriyama/Dragon-Ball/9781569319208', '9781569319208', 'Ação e aventura|Fantasia'),
    ('INK-0006', 'The Complete Maus', 'Art Spiegelman', 'Graphic novel', 'Edição encadernada', 'Pantheon', NULL, 'Art Spiegelman entrevista o pai, Vladek, sobre a perseguição aos judeus na Polônia e a sobrevivência em Auschwitz. Entre as lembranças do pai e as conversas gravadas pelo filho décadas depois, os quadrinhos expõem também as dificuldades de transmitir uma experiência familiar entre gerações. Edição integral em inglês.', 'https://images.penguinrandomhouse.com/cover/9780679406419', 'https://www.penguinrandomhouse.com/books/171065/the-complete-maus-by-art-spiegelman/', '9780679406419', 'Drama'),
    ('INK-3001', 'Akane-Banashi', 'Yuki Suenaga e Takamasa Moue', 'Mangá', 'Vol. 1', 'Editora JBC', NULL, 'Akane quer conquistar seu lugar no rakugo, arte em que uma pessoa sentada diante da plateia interpreta todos os personagens de uma história. A expulsão do pai do meio profissional dá à sua ambição um motivo pessoal. Edição brasileira da JBC, volume 1 (200 páginas; formato 13,2 × 20,0 cm; classificação indicativa: 14 anos).', 'https://editorajbc.com.br/wp-content/uploads/2024/08/akane-banashi-01-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/akane-banashi/vol/akane-banashi-01/', '9786555946789', 'Comédia|Drama'),
    ('INK-3002', 'Akira', 'Katsuhiro Otomo', 'Mangá', 'Vol. 1', 'Editora JBC', NULL, 'Em Neo-Tóquio, uma colisão durante uma corrida de motos põe Tetsuo sob custódia militar. Enquanto ele descobre um poder que mal consegue controlar, Kaneda acompanha o rastro de um segredo que a reconstrução da cidade tentou enterrar. Edição brasileira da JBC, volume 1 (362 páginas; formato 17,8 x 25,6 cm; classificação indicativa: 18 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2017/04/akira_01_p-150x216.jpg', 'https://editorajbc.com.br/mangas/colecao/akira/vol/akira-01/', '9788545702870', 'Ficção científica'),
    ('INK-3003', 'Alice in Borderland', 'Haro Aso', 'Mangá', 'Vol. 1', 'Editora JBC', NULL, 'Arisu e os amigos encontram uma Tóquio estranhamente vazia. Para permanecer nela, precisam vencer jogos cujas cartas anunciam o tipo e a dificuldade da prova, mas escondem o preço de confiar na pessoa errada. Edição brasileira da JBC, volume 1 (336 páginas; formato 13,2 x 20,0 cm; classificação indicativa: 18 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2023/08/alice-in-borderland-big-01-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/alice-in-borderland/vol/alice-in-borderland-01/', '9786555945157', 'Ficção científica|Mistério e suspense'),
    ('INK-3004', 'Ao Ashi', 'Yugo Kobayashi', 'Mangá', 'Vol. 1', 'Editora JBC', NULL, 'Ashito Aoi chega ao futebol de base de Tóquio com instinto para ler o campo e pouca formação tática. Disputar espaço numa equipe profissional exige aprender a enxergar a jogada também pelos olhos dos companheiros. Edição brasileira da JBC, volume 1 (192 páginas; formato 13,2 × 20,0 cm; classificação indicativa: 14 anos).', 'https://editorajbc.com.br/wp-content/uploads/2022/11/manga-ao-ashi-01-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/ao-ashi/vol/ao-ashi-craques-da-bola-01/', '9786555943849', 'Esportes'),
    ('INK-3005', 'Astro Boy', 'Osamu Tezuka', 'Mangá', 'Vol. 1', 'Editora JBC', NULL, 'Atom é um menino robô com força extraordinária num mundo em que humanos constroem máquinas à própria imagem. Cada aventura coloca em questão o que seus criadores devem às criaturas que aprenderam a pensar e a sentir. Edição brasileira da JBC, volume 1 (432 páginas; formato 15,0 × 21,0 cm; classificação indicativa: 14 anos).', 'https://editorajbc.com.br/wp-content/uploads/2024/08/astroboy-01-sobrecapa-150x209.jpg', 'https://editorajbc.com.br/mangas/colecao/astro-boy/vol/astro-boy-big-01/', '9786555946840', 'Ação e aventura|Ficção científica'),
    ('INK-3006', 'Bakuman', 'Tsugumi Ohba e Takeshi Obata', 'Mangá', 'Vol. 1', 'Editora JBC', NULL, 'Moritaka Mashiro desenha e Akito Takagi escreve. Decididos a publicar juntos, os colegas descobrem a distância entre uma boa ideia e uma série capaz de sobreviver a reuniões editoriais, prazos semanais e votações de leitores. Edição brasileira da JBC, volume 1 (200 páginas; formato 13,5 x 20,5 cm; classificação indicativa: livre).', 'https://editorajbc.com.br/wp-content/uploads/2011/08/manga-bakuman-01-capa-150x228.jpg', 'https://editorajbc.com.br/mangas/colecao/bakuman/vol/bakuman-01/', '9786555945195', 'Comédia|Romance'),
    ('INK-3007', 'Blade - A Lâmina do Imortal - Nova Edição', 'Hiroaki Samura', 'Mangá', 'Vol. 1', 'Editora JBC', NULL, 'Rin procura os espadachins que destruíram sua família. Manji, um guerreiro cujos ferimentos se fecham sozinhos, aceita acompanhá-la. A jornada põe em dúvida quem decide qual morte merece vingança. Edição brasileira da JBC, volume 1 (448 páginas; formato 13,5 x 20,5 cm; classificação indicativa: 18 anos).', 'https://editorajbc.com.br/wp-content/uploads/2024/03/blade-01-capa-2024-150x228.jpg', 'https://editorajbc.com.br/mangas/colecao/blade-a-lamina-do-imortal-nova-edicao/vol/blade-a-lamina-do-imortal-nova-edicao-01/', '9786555946284', 'Ação e aventura|Drama'),
    ('INK-3008', 'Blue Box', 'Kouji Miura', 'Mangá', 'Vol. 1', 'Editora JBC', NULL, 'Taiki chega cedo ao ginásio para treinar badminton e encontra Chinatsu, do basquete, praticando antes de todos. A convivência entre os atletas aproxima o primeiro amor da pressão por uma vaga nos campeonatos escolares. Edição brasileira da JBC, volume 1 (192 páginas; formato 13,2 x 20,0 cm; classificação indicativa: 10 anos).', 'https://editorajbc.com.br/wp-content/uploads/2024/06/blue-box-01-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/blue-box/vol/blue-box-01/', '9786555946802', 'Romance|Esportes'),
    ('INK-3009', 'Blue Exorcist', 'Kazue Katō', 'Mangá', 'Vol. 1', 'Editora JBC', NULL, 'Rin Okumura descobre uma ligação de sangue com o mundo que os exorcistas combatem. Ele escolhe treinar ao lado deles, embora revelar a origem de suas chamas possa custar a confiança dos colegas. Edição brasileira da JBC, volume 1 (200 páginas; formato 13,5 x 20,5 cm; classificação indicativa: 14 anos).', 'https://editorajbc.com.br/wp-content/uploads/2025/03/blue-exorcist-01-capa-150x228.jpg', 'https://editorajbc.com.br/mangas/colecao/blue-exorcist/vol/blue-exorcist-01-2/', '9786555948172', 'Ação e aventura|Drama|Fantasia'),
    ('INK-3010', 'Boa Noite Punpun', 'Inio Asano', 'Mangá', 'Vol. 1', 'Editora JBC', NULL, 'Punpun atravessa infância, adolescência e vida adulta representado como um pequeno pássaro num cenário realista. As promessas feitas a Aiko acompanham o personagem enquanto os adultos ao redor dele também perdem o rumo. Edição brasileira da JBC, volume 1 (432 páginas; formato 13,2 cm x 20 cm; classificação indicativa: 18 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2018/12/Boa-Noite-Punpun-01-Capa_p-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/boa-noite-punpun/vol/boa-noite-punpun-01/', '9788545709619', 'Drama'),
    ('INK-3011', 'Boys Run the Riot', 'Keito Gaku', 'Mangá', 'Vol. 1', 'Editora JBC', NULL, 'Ryo encontra na roupa uma maneira de expressar quem é fora das expectativas da escola. A amizade com Jin transforma o interesse por moda no projeto de criar uma marca própria. Edição brasileira da JBC, volume 1 (224 páginas; formato 13,2 × 20,0 cm; classificação indicativa: 16 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2022/11/manga-boys-run-the-riot-01-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/boys-run-the-riot/vol/boys-run-the-riot-01/', '9786555943702', 'LGBTQIAPN+|Drama'),
    ('INK-3012', 'CDZ - Next Dimension', 'Masami Kurumada', 'Mangá', 'Vol. 1', 'Editora JBC', NULL, 'Para tentar salvar Seiya, Atena e seus companheiros voltam ao tempo da guerra sagrada anterior. No Santuário de outra época, rostos desconhecidos ocupam as armaduras que os heróis julgavam conhecer. Edição brasileira da JBC, volume 1 (168 páginas; formato 13,5 x 20,0 cm; classificação indicativa: 14 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2016/02/capa_cdz_next_dimension_a_saga_de_hades_01_g-150x222.jpg', 'https://editorajbc.com.br/mangas/colecao/cdz-next-dimension/vol/cdz-next-dimension-a-saga-de-hades-01/', '9788577874262', 'Ação e aventura|Fantasia'),
    ('INK-3013', 'CDZ - The Lost Canvas Gaiden ESPECIAL', 'Masami Kurumada e Shiori Teshirogi', 'Mangá', 'Vol. 1', 'Editora JBC', NULL, 'As histórias acompanham os Cavaleiros de Ouro da geração de Lost Canvas em missões próprias. Longe do centro da guerra contra Hades, cada guerreiro revela o custo pessoal de proteger sua casa zodiacal. Edição brasileira da JBC, volume 1 (200 páginas; formato 13,2 x 20,0 cm; classificação indicativa: 14 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2022/10/lost-canvas-gaiden-01-capa-p-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/cdz-the-lost-canvas-gaiden-esp/vol/cdz-the-lost-canvas-gaiden-esp-01/', '9788577875504', ''),
    ('INK-3014', 'CDZ Saint Seiya - Final Edition', 'Masami Kurumada', 'Mangá', 'Vol. 1', 'Editora JBC', NULL, 'Seiya conquista a Armadura de Pégaso e retorna ao Japão em busca da irmã. Seu caminho se cruza com o dos jovens cavaleiros que arriscam a vida para defender Atena. Edição brasileira da JBC, volume 1 (272 páginas; formato 13,2 × 20,0 cm; classificação indicativa: 14 anos).', 'https://editorajbc.com.br/wp-content/uploads/2024/10/cdz-final-edition-01-capa-150x222.jpg', 'https://editorajbc.com.br/mangas/colecao/saint-seiya-final-edition/vol/cavaleiros-do-zodiaco-saint-seiya-final-edition-01/', '9786555947366', 'Ação e aventura'),
    ('INK-3015', 'Cardcaptor Sakura Clear Card Arc', 'CLAMP', 'Mangá', 'Vol. 1', 'Editora JBC', NULL, 'Ao começar uma nova etapa na escola, Sakura percebe que as cartas que reuniu se tornaram transparentes. Sonhos enigmáticos e novos fenômenos mágicos levam a garota a investigar o que aconteceu com seus poderes. Edição brasileira da JBC, volume 1 (160 páginas; formato 13,2 cm x 20 cm; classificação indicativa: 10 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2019/09/Cardcaptor-Sakura-Clear-Card-Arc-01-Sobrecapa_p-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/cardcaptor-sakura-clear-card-arc/vol/cardcaptor-sakura-clear-card-arc-01/', '9788545711889', 'Fantasia'),
    ('INK-3016', 'Chi''s Sweet Home', 'Kanata Konami', 'Mangá', 'Vol. 1', 'Editora JBC', NULL, 'Uma gatinha se perde da mãe e encontra abrigo na casa da família Yamada. Do ponto de vista de Chi, uma porta fechada, a caixa de areia e a chegada de um visitante viram grandes acontecimentos. Edição brasileira da JBC, volume 1 (168 páginas; formato 17,0 x 24,0 cm; classificação indicativa: livre).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2021/03/chis-sweet-home-01-capa-p-150x209.jpg', 'https://editorajbc.com.br/mangas/colecao/chis-sweet-home/vol/chis-sweet-home-01/', '9786555940831', 'Comédia'),
    ('INK-3017', 'Dragon Quest - The Adventure of Dai', 'Riku Sanjo e Koji Inada', 'Mangá', 'Vol. 1', 'Editora JBC', NULL, 'Criado numa ilha habitada por monstros, Dai sonha com as façanhas dos heróis. O retorno das forças do mal põe sua coragem à prova e o obriga a sair da ilha para defender o mundo que mal conhece. Edição brasileira da JBC, volume 1 (336 páginas; formato 14,6 x 21,0 cm; classificação indicativa: 10 anos).', 'https://editorajbc.com.br/wp-content/uploads/2026/02/dragon-quest-dai-1-capa-202501-150x216.jpg', 'https://editorajbc.com.br/mangas/colecao/dragon-quest-as-aventuras-de-dai/vol/dragon-quest-the-adventure-of-dai-01/', '9788545715290', 'Ação e aventura|Fantasia'),
    ('INK-3018', 'Final Fantasy - Lost Stranger', 'Hazuki Minase e Itsuki Kameya', 'Mangá', 'Vol. 1', 'Editora JBC', NULL, 'Dois irmãos são transportados para um mundo que reconhecem dos jogos de Final Fantasy. O conhecimento das regras parece uma vantagem até que uma perda torna urgente descobrir se a magia de ressurreição realmente existe. Edição brasileira da JBC, volume 1 (224 páginas; formato 13,2 × 20,0 cm; classificação indicativa: 14 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2022/04/final-fantasy-01-capa-p-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/final-fantasy-lost-stranger/vol/final-fantasy-lost-stranger-01/', '9786555942743', 'Fantasia|Ficção científica'),
    ('INK-3019', 'Flying Witch', 'Chihiro Ishizuka', 'Mangá', 'Vol. 1', 'Editora JBC', NULL, 'Makoto vai morar com parentes no interior para se formar como bruxa. Entre a horta, a escola e as visitas de seres sobrenaturais, aprender magia também significa aprender os ritmos da nova casa. Edição brasileira da JBC, volume 1 (168 páginas; formato 13,2 × 20,0 cm; classificação indicativa: livre).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2023/07/flying-witch-01-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/flying-witch/vol/flying-witch-01/', '9786555944976', 'Fantasia|Comédia|Slice of life'),
    ('INK-3020', 'Fênix', 'Osamu Tezuka', 'Mangá', 'Vol. 1', 'Editora JBC', NULL, 'Osamu Tezuka alterna épocas remotas e futuros distantes para acompanhar pessoas que perseguem a ave de fogo. A promessa de vencer a morte expõe desejos que se repetem mesmo quando as civilizações desaparecem. Edição brasileira da JBC, volume 1 (632 páginas; formato 15,0 × 21,0 cm; classificação indicativa: 14 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2023/11/fenix-01-sobrecapa-150x210.jpg', 'https://editorajbc.com.br/mangas/colecao/fenix/vol/fenix-01/', '9786555945737', 'Drama|Fantasia'),
    ('INK-3021', 'Haikyu!!', 'Haruichi Furudate', 'Mangá', 'Vol. 1', 'Editora JBC', NULL, 'Hinata quer voar sobre a rede apesar da baixa estatura. Ao entrar no time de vôlei do Karasuno, precisa aprender a jogar com Kageyama, o levantador que antes o derrotou e que agora pode aproveitar melhor sua velocidade. Edição brasileira da JBC, volume 1 (392 páginas; formato 13,2 × 20,0 cm; classificação indicativa: livre).', 'https://editorajbc.com.br/wp-content/uploads/2021/05/haikyu-big-01-capa-p-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/haikyu/vol/haikyu-01/', '9786555941296', 'Esportes|Comédia|Drama'),
    ('INK-3022', 'Hellsing ESP.', 'Kouta Hirano', 'Mangá', 'Vol. 1', 'Editora JBC', NULL, 'A organização Hellsing protege a Inglaterra de ameaças sobrenaturais com a ajuda de Alucard, um vampiro a seu serviço. A policial Seras Victoria entra nesse mundo e precisa descobrir o que ainda significa agir como humana. Edição brasileira da JBC, volume 1 (208 páginas; formato 13,5 x 20,5 cm; classificação indicativa: 18 anos).', 'https://editorajbc.com.br/wp-content/uploads/2025/06/hellsing-01-capa-2025-p-150x228.jpg', 'https://editorajbc.com.br/mangas/colecao/hellsing-esp/vol/hellsing-especial-01/', '9786555949070', 'Ação e aventura'),
    ('INK-3023', 'InuYasha Wideban', 'Rumiko Takahashi', 'Mangá', 'Vol. 1', 'Editora JBC', NULL, 'Kagome atravessa um poço que liga sua casa ao Japão feudal. Ao lado de Inuyasha, procura os fragmentos de uma joia cobiçada por humanos e demônios, enquanto aprende a viver entre duas épocas. Edição brasileira da JBC, volume 1 (354 páginas; formato 12,8 x 18,2 cm; classificação indicativa: 14 anos).', 'https://editorajbc.com.br/wp-content/uploads/2021/08/inu-yasha-wideban-01-sobrecapa-layout-p-150x207.jpg', 'https://editorajbc.com.br/mangas/colecao/inuyasha-wideban/vol/inuyasha-wideban-01/', '9786555941715', ''),
    ('INK-3024', 'Kamen Rider Kuuga BIG', 'Toshiki Inoue , Hitotsu Yokoshima e Shotaro Ishinomori', 'Mangá', 'Vol. 1', 'Editora JBC', NULL, 'O despertar de seres antigos transforma investigações policiais em uma corrida contra mortes inexplicáveis. Um poder ligado às ruínas dá a um jovem a capacidade de enfrentar os inimigos sob a forma de Kuuga. Edição brasileira da JBC, volume 1 (408 páginas; formato 13,2 × 20,0 cm; classificação indicativa: 16 anos).', 'https://editorajbc.com.br/wp-content/uploads/2021/09/kamen-rider-kuuga-01-capa-p-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/kamen-rider-kuuga-big/vol/kamen-rider-kuuga-big-01/', '9786555942217', 'Ação e aventura'),
    ('INK-3025', 'Medalist', 'Tsuruma Ikada', 'Mangá', 'Vol. 1', 'Editora JBC', NULL, 'Inori quer competir na patinação artística e encontra em Tsukasa um treinador disposto a apostar nela. Saltos e programas ganham peso numa modalidade em que começar tarde já é tratado como desvantagem. Edição brasileira da JBC, volume 1 (232 páginas; formato 13,2 × 20,0 cm; classificação indicativa: livre).', 'https://editorajbc.com.br/wp-content/uploads/2025/10/medalist-capa-01-p-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/medalist/vol/medalist-01/', '9788545715573', 'Drama|Esportes'),
    ('INK-3026', 'My Home Hero', 'Naoki Yamakawa e Masashi Asaki', 'Mangá', 'Vol. 1', 'Editora JBC', NULL, 'Ao tentar proteger a filha de um relacionamento violento, um pai de família atrai a atenção do crime organizado. Seu repertório de romances policiais deixa de ser passatempo quando ele precisa sustentar a própria versão dos acontecimentos. Edição brasileira da JBC, volume 1 (192 páginas; formato 13,2 × 20,0 cm; classificação indicativa: 18 anos).', 'https://editorajbc.com.br/wp-content/uploads/2023/10/my-home-hero-01-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/my-home-hero/vol/my-home-hero-01/', '9786555945669', 'Drama|Mistério e suspense'),
    ('INK-3027', 'Nausicaä do Vale do Vento', 'Hayao Miyazaki', 'Mangá', 'Vol. 1', 'Editora JBC', NULL, 'Nausicaä explora uma floresta tóxica que avança sobre o território humano. Quando reinos vizinhos entram em guerra, compreender os insetos e o solo pode ser mais importante para o Vale do Vento do que vencer uma batalha. Edição brasileira da JBC, volume 1 (136 páginas; formato 18,2 cm x 25,6 cm).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2022/06/nausicaa-01-capa-150x211.jpg', 'https://editorajbc.com.br/mangas/colecao/nausicaa-do-vale-do-vento/vol/nausicaa-do-vale-do-vento-01/', '9786555942521', 'Ação e aventura|Ficção científica'),
    ('INK-3028', 'Neon Genesis Evangelion - Edição de Colecionador', 'Yoshiyuki Sadamoto e Hideaki Anno', 'Mangá', 'Vol. 1', 'Editora JBC', NULL, 'Shinji é chamado pelo pai para pilotar uma unidade Evangelion contra os Anjos. A defesa da cidade depende de adolescentes que conhecem pouco das máquinas e ainda menos dos planos dos adultos que os comandam. Edição brasileira da JBC, volume 1 (336 páginas; formato 15,0 × 21,0 cm; classificação indicativa: 16 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2022/10/neon-genesis-evangelion-collectors-edition-01-capa-150x210.jpg', 'https://editorajbc.com.br/mangas/colecao/neon-genesis-evangelion-edicao-de-colecionador/vol/neon-genesis-evangelion-collectors-edition-01/', '9786555943412', 'Ação e aventura|Drama|Ficção científica'),
    ('INK-3029', 'Não Chame de Mistério', 'Yumi Tamura', 'Mangá', 'Vol. 1', 'Editora JBC', NULL, 'Totono percebe contradições que passam despercebidas por quem investiga um crime. Suas conversas longas e pouco convencionais desmontam tanto álibis quanto certezas sobre o comportamento das vítimas. Edição brasileira da JBC, volume 1 (192 páginas; formato 13,2 × 20,0 cm; classificação indicativa: 16 anos).', 'https://editorajbc.com.br/wp-content/uploads/2024/02/nao-chame-de-misterio-01-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/nao-chame-de-misterio/vol/nao-chame-de-misterio-01/', '9786555945744', 'Ação e aventura|Comédia|Mistério e suspense'),
    ('INK-3030', 'Parasyte – Edição Especial Colorida', 'Hitoshi Iwaaki', 'Mangá', 'Vol. 1', 'Editora JBC', NULL, 'Um parasita falha ao tomar o cérebro de Shinichi e se instala em sua mão direita. Obrigados a compartilhar o corpo, rapaz e criatura enfrentam outros invasores sem concordar sequer sobre o valor de uma vida humana. Edição brasileira da JBC, volume 1 (280 páginas; formato 15,0 x 21,0 cm; classificação indicativa: 16 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2024/03/manga-parasyte-01-sobrecapa-150x210.jpg', 'https://editorajbc.com.br/mangas/colecao/parasyte-edicao-especial-colorida/vol/parasyte-edicao-especial-colorida-01/', '9786555946253', 'Ficção científica|Horror'),
    ('INK-3031', 'Sailor Moon Eternal Editon', 'Naoko Takeuchi', 'Mangá', 'Vol. 1', 'Editora JBC', NULL, 'Usagi descobre que pode se transformar em Sailor Moon. Reunir as demais guardiãs e proteger a Terra a aproxima de lembranças de outro reino que explicam por que a batalha chegou até ela. Edição brasileira da JBC, volume 1 (296 páginas; formato 15,2 × 21,0 cm; classificação indicativa: livre).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2024/07/sailor-moon-eternal-edition-01-capa-150x210.jpg', 'https://editorajbc.com.br/mangas/colecao/sailor-moon-eternal-editon/vol/sailor-moon-eternal-edition-01/', '9786555947830', 'Fantasia|Ação e aventura'),
    ('INK-3032', 'Saintia Shô', 'Chimaki Kuori', 'Mangá', 'Vol. 1', 'Editora JBC', NULL, 'Shoko entra em contato com as guerreiras que servem diretamente a Atena. A ameaça da deusa da discórdia transforma a procura pela irmã em uma batalha ligada ao destino do Santuário. Edição brasileira da JBC, volume 1 (184 páginas; formato 13,5 x 20,5 cm; classificação indicativa: 14 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2016/09/Saintia-Shô-01-Capa-150x228.jpg', 'https://editorajbc.com.br/mangas/colecao/saintia-sho/vol/saintia-sho-01/', '9788545701989', 'Ação e aventura|Fantasia'),
    ('INK-3033', 'Sangatsu no Lion - O Leão de Março', 'Chica Umino', 'Mangá', 'Vol. 1', 'Editora JBC', NULL, 'Rei Kiriyama joga shogi profissionalmente ainda adolescente e mora sozinho. As partidas revelam uma parte de sua história, enquanto a convivência com as irmãs Kawamoto abre espaço para uma vida além do tabuleiro. Edição brasileira da JBC, volume 1 (184 páginas; formato 13,2 × 20,0 cm; classificação indicativa: 16 anos).', 'https://editorajbc.com.br/wp-content/uploads/2023/01/manga-sangatsu-no-lion-01-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/sangatsu-no-lion/vol/sangatsu-no-lion-o-leao-de-marco-01/', '9786555943993', 'Slice of life|Drama'),
    ('INK-3034', 'Shaman King BIG', 'Hiroyuki Takei', 'Mangá', 'Vol. 1', 'Editora JBC', NULL, 'Yoh Asakura vê espíritos e luta ao lado do samurai Amidamaru. Para disputar o título de Shaman King, terá de compreender o que move os outros médiuns a buscar tamanho poder. Edição brasileira da JBC, volume 1 (392 páginas; formato 15,0 × 21,0 cm; classificação indicativa: 14 anos).', 'https://editorajbc.com.br/wp-content/uploads/2021/07/shaman-king-big-01-sobrecapa-p-150x210.jpg', 'https://editorajbc.com.br/mangas/colecao/shaman-king-big/vol/shaman-king-big-01/', '9786555941548', 'Ação e aventura|Comédia'),
    ('INK-3035', 'Skip & Loafer', 'Misaki Takamatsu', 'Mangá', 'Vol. 1', 'Editora JBC', NULL, 'Mitsumi chega do interior para estudar em Tóquio com um plano de carreira detalhado. O primeiro dia já escapa do roteiro, e a amizade com Shima muda o que ela espera da escola e de si mesma. Edição brasileira da JBC, volume 1 (200 páginas; formato 12,8 × 18,2 cm; classificação indicativa: 12 anos).', 'https://editorajbc.com.br/wp-content/uploads/2024/08/skip-and-loafer-01-capa-150x210.jpg', 'https://editorajbc.com.br/mangas/colecao/skip-to-loafer/vol/skip-loafer-01/', '9786555946871', 'Drama'),
    ('INK-3036', 'Akane-Banashi', 'Yuki Suenaga e Takamasa Moue', 'Mangá', 'Vol. 2', 'Editora JBC', NULL, 'Akane quer conquistar seu lugar no rakugo, arte em que uma pessoa sentada diante da plateia interpreta todos os personagens de uma história. A expulsão do pai do meio profissional dá à sua ambição um motivo pessoal. Edição brasileira da JBC, volume 2 (208 páginas; formato 13,2 × 20,0 cm; classificação indicativa: 14 anos).', 'https://editorajbc.com.br/wp-content/uploads/2025/01/manga-akane-banashi-01-capajpg-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/akane-banashi/vol/akane-banashi-02/', '9786555947700', 'Comédia|Drama'),
    ('INK-3037', 'Akira', 'Katsuhiro Otomo', 'Mangá', 'Vol. 2', 'Editora JBC', NULL, 'Em Neo-Tóquio, uma colisão durante uma corrida de motos põe Tetsuo sob custódia militar. Enquanto ele descobre um poder que mal consegue controlar, Kaneda acompanha o rastro de um segredo que a reconstrução da cidade tentou enterrar. Edição brasileira da JBC, volume 2 (296+8 coloridas páginas; formato 17,8 x 25,6 cm; classificação indicativa: 18 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2018/04/AKIRA-02-Sobrecapa_p-150x216.jpg', 'https://editorajbc.com.br/mangas/colecao/akira/vol/akira-02/', '9788545703679', 'Ficção científica'),
    ('INK-3038', 'Alice in Borderland', 'Haro Aso', 'Mangá', 'Vol. 2', 'Editora JBC', NULL, 'Arisu e os amigos encontram uma Tóquio estranhamente vazia. Para permanecer nela, precisam vencer jogos cujas cartas anunciam o tipo e a dificuldade da prova, mas escondem o preço de confiar na pessoa errada. Edição brasileira da JBC, volume 2 (304 páginas; formato 13,2 x 20,0 cm; classificação indicativa: 18 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2023/09/alice-in-borderland-big-02-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/alice-in-borderland/vol/alice-in-borderland-02/', '9786555945515', 'Ficção científica|Mistério e suspense'),
    ('INK-3039', 'Ao Ashi', 'Yugo Kobayashi', 'Mangá', 'Vol. 2', 'Editora JBC', NULL, 'Ashito Aoi chega ao futebol de base de Tóquio com instinto para ler o campo e pouca formação tática. Disputar espaço numa equipe profissional exige aprender a enxergar a jogada também pelos olhos dos companheiros. Edição brasileira da JBC, volume 2 (192 páginas; formato 13,2 × 20,0 cm; classificação indicativa: 14 anos).', 'https://editorajbc.com.br/wp-content/uploads/2023/02/ao-ashi-02-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/ao-ashi/vol/ao-ashi-craques-da-bola-02/', '9786555944075', 'Esportes'),
    ('INK-3040', 'Astro Boy', 'Osamu Tezuka', 'Mangá', 'Vol. 2', 'Editora JBC', NULL, 'Atom é um menino robô com força extraordinária num mundo em que humanos constroem máquinas à própria imagem. Cada aventura coloca em questão o que seus criadores devem às criaturas que aprenderam a pensar e a sentir. Edição brasileira da JBC, volume 2 (448 páginas; formato 15,0 x 21,0 cm; classificação indicativa: 14 anos).', 'https://editorajbc.com.br/wp-content/uploads/2024/12/astroboy-02-sobrecapa-150x209.jpg', 'https://editorajbc.com.br/mangas/colecao/astro-boy/vol/astro-boy-big-02/', '9786555947519', 'Ação e aventura|Ficção científica'),
    ('INK-3041', 'Bakuman', 'Tsugumi Ohba e Takeshi Obata', 'Mangá', 'Vol. 2', 'Editora JBC', NULL, 'Moritaka Mashiro desenha e Akito Takagi escreve. Decididos a publicar juntos, os colegas descobrem a distância entre uma boa ideia e uma série capaz de sobreviver a reuniões editoriais, prazos semanais e votações de leitores. Edição brasileira da JBC, volume 2 (200 páginas; formato 13,5 x 20,5 cm; classificação indicativa: livre).', 'https://editorajbc.com.br/wp-content/uploads/2011/09/manga-bakuman-02-capa-150x228.jpg', 'https://editorajbc.com.br/mangas/colecao/bakuman/vol/bakuman-02/', '9786555945188', 'Comédia|Romance'),
    ('INK-3042', 'Blade - A Lâmina do Imortal - Nova Edição', 'Hiroaki Samura', 'Mangá', 'Vol. 2', 'Editora JBC', NULL, 'Rin procura os espadachins que destruíram sua família. Manji, um guerreiro cujos ferimentos se fecham sozinhos, aceita acompanhá-la. A jornada põe em dúvida quem decide qual morte merece vingança. Edição brasileira da JBC, volume 2 (448 páginas; formato 13,5 x 20,5 cm; classificação indicativa: 18 anos).', 'https://editorajbc.com.br/wp-content/uploads/2024/04/blade-02-capa-150x228.jpg', 'https://editorajbc.com.br/mangas/colecao/blade-a-lamina-do-imortal-nova-edicao/vol/blade-a-lamina-do-imortal-nova-edicao-02/', '9786555946468', 'Ação e aventura|Drama'),
    ('INK-3043', 'Blue Box', 'Kouji Miura', 'Mangá', 'Vol. 2', 'Editora JBC', NULL, 'Taiki chega cedo ao ginásio para treinar badminton e encontra Chinatsu, do basquete, praticando antes de todos. A convivência entre os atletas aproxima o primeiro amor da pressão por uma vaga nos campeonatos escolares. Edição brasileira da JBC, volume 2 (200 páginas; formato 13,2 x 20,0 cm; classificação indicativa: 10 anos).', 'https://editorajbc.com.br/wp-content/uploads/2024/10/blue-box-02-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/blue-box/vol/blue-box-02/', '9786555947274', 'Romance|Esportes'),
    ('INK-3044', 'Blue Exorcist', 'Kazue Katō', 'Mangá', 'Vol. 2', 'Editora JBC', NULL, 'Rin Okumura descobre uma ligação de sangue com o mundo que os exorcistas combatem. Ele escolhe treinar ao lado deles, embora revelar a origem de suas chamas possa custar a confiança dos colegas. Edição brasileira da JBC, volume 2 (208 páginas; formato 13,5 x 20,5 cm; classificação indicativa: 14 anos).', 'https://editorajbc.com.br/wp-content/uploads/2025/03/blue-exorcist-02-capa-2025-150x228.jpg', 'https://editorajbc.com.br/mangas/colecao/blue-exorcist/vol/blue-exorcist-02-2/', '9786555948189', 'Ação e aventura|Drama|Fantasia'),
    ('INK-3045', 'Boa Noite Punpun', 'Inio Asano', 'Mangá', 'Vol. 2', 'Editora JBC', NULL, 'Punpun atravessa infância, adolescência e vida adulta representado como um pequeno pássaro num cenário realista. As promessas feitas a Aiko acompanham o personagem enquanto os adultos ao redor dele também perdem o rumo. Edição brasileira da JBC, volume 2 (432 páginas; formato 13,2 cm x 20 cm; classificação indicativa: 18 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2018/12/Boa-Noite-Punpun-02-Capa_p-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/boa-noite-punpun/vol/boa-noite-punpun-02/', '9788545709602', 'Drama'),
    ('INK-3046', 'Boys Run the Riot', 'Keito Gaku', 'Mangá', 'Vol. 2', 'Editora JBC', NULL, 'Ryo encontra na roupa uma maneira de expressar quem é fora das expectativas da escola. A amizade com Jin transforma o interesse por moda no projeto de criar uma marca própria. Edição brasileira da JBC, volume 2 (176 páginas; formato 13,2 × 20,0 cm; classificação indicativa: 16 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2022/11/manga-boys-run-the-riot-02-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/boys-run-the-riot/vol/boys-run-the-riot-02/', '9786555943719', 'LGBTQIAPN+|Drama'),
    ('INK-3047', 'CDZ - Next Dimension', 'Masami Kurumada', 'Mangá', 'Vol. 2', 'Editora JBC', NULL, 'Para tentar salvar Seiya, Atena e seus companheiros voltam ao tempo da guerra sagrada anterior. No Santuário de outra época, rostos desconhecidos ocupam as armaduras que os heróis julgavam conhecer. Edição brasileira da JBC, volume 2 (152 páginas; formato 13,5 x 20,0 cm; classificação indicativa: 14 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2016/02/capa_cdz_next_dimension_a_saga_de_hades_02_g-150x222.jpg', 'https://editorajbc.com.br/mangas/colecao/cdz-next-dimension/vol/cdz-next-dimension-a-saga-de-hades-02/', '9788577874460', 'Ação e aventura|Fantasia'),
    ('INK-3048', 'CDZ - The Lost Canvas Gaiden ESPECIAL', 'Masami Kurumada e Shiori Teshirogi', 'Mangá', 'Vol. 2', 'Editora JBC', NULL, 'As histórias acompanham os Cavaleiros de Ouro da geração de Lost Canvas em missões próprias. Longe do centro da guerra contra Hades, cada guerreiro revela o custo pessoal de proteger sua casa zodiacal. Edição brasileira da JBC, volume 2 (200 páginas; formato 13,2 x 20,0 cm; classificação indicativa: 14 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2022/10/lost-canvas-gaiden-02-p-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/cdz-the-lost-canvas-gaiden-esp/vol/cdz-the-lost-canvas-gaiden-esp-02/', '9788577875665', ''),
    ('INK-3049', 'CDZ Saint Seiya - Final Edition', 'Masami Kurumada', 'Mangá', 'Vol. 2', 'Editora JBC', NULL, 'Seiya conquista a Armadura de Pégaso e retorna ao Japão em busca da irmã. Seu caminho se cruza com o dos jovens cavaleiros que arriscam a vida para defender Atena. Edição brasileira da JBC, volume 2 (296 páginas; formato 13,2 × 20,0 cm; classificação indicativa: 14 anos).', 'https://editorajbc.com.br/wp-content/uploads/2025/01/cdz-final-edition-02-capa-mdg-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/saint-seiya-final-edition/vol/cavaleiros-do-zodiaco-saint-seiya-final-edition-02/', '9786555947953', 'Ação e aventura'),
    ('INK-3050', 'Cardcaptor Sakura Clear Card Arc', 'CLAMP', 'Mangá', 'Vol. 2', 'Editora JBC', NULL, 'Ao começar uma nova etapa na escola, Sakura percebe que as cartas que reuniu se tornaram transparentes. Sonhos enigmáticos e novos fenômenos mágicos levam a garota a investigar o que aconteceu com seus poderes. Edição brasileira da JBC, volume 2 (160 páginas; formato 13,2 cm x 20 cm; classificação indicativa: 10 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2019/09/Cardcaptor-Sakura-Clear-Card-Arc-02-Sobrecapa_p-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/cardcaptor-sakura-clear-card-arc/vol/cardcaptor-sakura-clear-card-arc-02/', '9788545711896', 'Fantasia'),
    ('INK-3051', 'Chi''s Sweet Home', 'Kanata Konami', 'Mangá', 'Vol. 2', 'Editora JBC', NULL, 'Uma gatinha se perde da mãe e encontra abrigo na casa da família Yamada. Do ponto de vista de Chi, uma porta fechada, a caixa de areia e a chegada de um visitante viram grandes acontecimentos. Edição brasileira da JBC, volume 2 (160 páginas; formato 17,0 x 24,0 cm; classificação indicativa: livre).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2021/07/chi-s-sweet-home-02-capa-p-150x209.jpg', 'https://editorajbc.com.br/mangas/colecao/chis-sweet-home/vol/chis-sweet-home-02/', '9786555941265', 'Comédia'),
    ('INK-3052', 'Dragon Quest - The Adventure of Dai', 'Riku Sanjo e Koji Inada', 'Mangá', 'Vol. 2', 'Editora JBC', NULL, 'Criado numa ilha habitada por monstros, Dai sonha com as façanhas dos heróis. O retorno das forças do mal põe sua coragem à prova e o obriga a sair da ilha para defender o mundo que mal conhece. Edição brasileira da JBC, volume 2 (336 páginas; formato 14,6 x 21,0 cm; classificação indicativa: 10 anos).', 'https://editorajbc.com.br/wp-content/uploads/2026/05/dragon-quest-dai-2-c1-150x216.jpg', 'https://editorajbc.com.br/mangas/colecao/dragon-quest-as-aventuras-de-dai/vol/dragon-quest-the-adventure-of-dai-02/', '9788545716990', 'Ação e aventura|Fantasia'),
    ('INK-3053', 'Final Fantasy - Lost Stranger', 'Hazuki Minase e Itsuki Kameya', 'Mangá', 'Vol. 2', 'Editora JBC', NULL, 'Dois irmãos são transportados para um mundo que reconhecem dos jogos de Final Fantasy. O conhecimento das regras parece uma vantagem até que uma perda torna urgente descobrir se a magia de ressurreição realmente existe. Edição brasileira da JBC, volume 2 (232 páginas; formato 13,2 × 20,0 cm; classificação indicativa: 14 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2022/07/manga-final-fantasy-lost-stranger-02-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/final-fantasy-lost-stranger/vol/final-fantasy-lost-stranger-02/', '9786555943108', 'Fantasia|Ficção científica'),
    ('INK-3054', 'Flying Witch', 'Chihiro Ishizuka', 'Mangá', 'Vol. 2', 'Editora JBC', NULL, 'Makoto vai morar com parentes no interior para se formar como bruxa. Entre a horta, a escola e as visitas de seres sobrenaturais, aprender magia também significa aprender os ritmos da nova casa. Edição brasileira da JBC, volume 2 (168 páginas; formato 13,2 × 20,0 cm; classificação indicativa: livre).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2023/07/flying-witch-02-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/flying-witch/vol/flying-witch-02/', '9786555944983', 'Fantasia|Comédia|Slice of life'),
    ('INK-3055', 'Fênix', 'Osamu Tezuka', 'Mangá', 'Vol. 2', 'Editora JBC', NULL, 'Osamu Tezuka alterna épocas remotas e futuros distantes para acompanhar pessoas que perseguem a ave de fogo. A promessa de vencer a morte expõe desejos que se repetem mesmo quando as civilizações desaparecem. Edição brasileira da JBC, volume 2 (696 páginas; formato 15,0 × 21,0 cm; classificação indicativa: 14 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2024/04/fenix-02-sobrecapa-150x210.jpg', 'https://editorajbc.com.br/mangas/colecao/fenix/vol/fenix-02/', '9786555946321', 'Drama|Fantasia'),
    ('INK-3056', 'Haikyu!!', 'Haruichi Furudate', 'Mangá', 'Vol. 2', 'Editora JBC', NULL, 'Hinata quer voar sobre a rede apesar da baixa estatura. Ao entrar no time de vôlei do Karasuno, precisa aprender a jogar com Kageyama, o levantador que antes o derrotou e que agora pode aproveitar melhor sua velocidade. Edição brasileira da JBC, volume 2 (400 páginas; formato 13,2 × 20,0 cm; classificação indicativa: livre).', 'https://editorajbc.com.br/wp-content/uploads/2021/09/haikyu-big-02-capa-p-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/haikyu/vol/haikyu-02/', '9786555942057', 'Esportes|Comédia|Drama'),
    ('INK-3057', 'Hellsing ESP.', 'Kouta Hirano', 'Mangá', 'Vol. 2', 'Editora JBC', NULL, 'A organização Hellsing protege a Inglaterra de ameaças sobrenaturais com a ajuda de Alucard, um vampiro a seu serviço. A policial Seras Victoria entra nesse mundo e precisa descobrir o que ainda significa agir como humana. Edição brasileira da JBC, volume 2 (192 páginas; formato 13,5 x 20,5 cm; classificação indicativa: 18 anos).', 'https://editorajbc.com.br/wp-content/uploads/2025/08/hellsing-02-capa-p-150x228.jpg', 'https://editorajbc.com.br/mangas/colecao/hellsing-esp/vol/hellsing-especial-02/', '9786555949599', 'Ação e aventura'),
    ('INK-3058', 'InuYasha Wideban', 'Rumiko Takahashi', 'Mangá', 'Vol. 2', 'Editora JBC', NULL, 'Kagome atravessa um poço que liga sua casa ao Japão feudal. Ao lado de Inuyasha, procura os fragmentos de uma joia cobiçada por humanos e demônios, enquanto aprende a viver entre duas épocas. Edição brasileira da JBC, volume 2 (345 páginas; formato 12,8 x 18,2 cm; classificação indicativa: 14 anos).', 'https://editorajbc.com.br/wp-content/uploads/2022/01/inuyasha-wideban-02-layout-sobrecapa-150x213.jpg', 'https://editorajbc.com.br/mangas/colecao/inuyasha-wideban/vol/inuyasha-wideban-02/', '9786555942132', ''),
    ('INK-3059', 'Kamen Rider Kuuga BIG', 'Toshiki Inoue , Hitotsu Yokoshima e Shotaro Ishinomori', 'Mangá', 'Vol. 2', 'Editora JBC', NULL, 'O despertar de seres antigos transforma investigações policiais em uma corrida contra mortes inexplicáveis. Um poder ligado às ruínas dá a um jovem a capacidade de enfrentar os inimigos sob a forma de Kuuga. Edição brasileira da JBC, volume 2 (440 páginas; formato 13,2 × 20,0 cm; classificação indicativa: 16 anos).', 'https://editorajbc.com.br/wp-content/uploads/2022/02/kamen-rider-kuuga-02-capa-p-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/kamen-rider-kuuga-big/vol/kamen-rider-kuuga-big-02/', '9786555942668', 'Ação e aventura'),
    ('INK-3060', 'Medalist', 'Tsuruma Ikada', 'Mangá', 'Vol. 2', 'Editora JBC', NULL, 'Inori quer competir na patinação artística e encontra em Tsukasa um treinador disposto a apostar nela. Saltos e programas ganham peso numa modalidade em que começar tarde já é tratado como desvantagem. Edição brasileira da JBC, volume 2 (200 páginas; formato 13,2 × 20,0 cm; classificação indicativa: livre).', 'https://editorajbc.com.br/wp-content/uploads/2026/01/medalist-2-capa-p-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/medalist/vol/medalist-02/', '9788545716068', 'Drama|Esportes'),
    ('INK-3061', 'My Home Hero', 'Naoki Yamakawa e Masashi Asaki', 'Mangá', 'Vol. 2', 'Editora JBC', NULL, 'Ao tentar proteger a filha de um relacionamento violento, um pai de família atrai a atenção do crime organizado. Seu repertório de romances policiais deixa de ser passatempo quando ele precisa sustentar a própria versão dos acontecimentos. Edição brasileira da JBC, volume 2 (200 páginas; formato 13,2 × 20,0 cm; classificação indicativa: 18 anos).', 'https://editorajbc.com.br/wp-content/uploads/2024/02/my-home-hero-02-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/my-home-hero/vol/my-home-hero-02/', '9786555946055', 'Drama|Mistério e suspense'),
    ('INK-3062', 'Nausicaä do Vale do Vento', 'Hayao Miyazaki', 'Mangá', 'Vol. 2', 'Editora JBC', NULL, 'Nausicaä explora uma floresta tóxica que avança sobre o território humano. Quando reinos vizinhos entram em guerra, compreender os insetos e o solo pode ser mais importante para o Vale do Vento do que vencer uma batalha. Edição brasileira da JBC, volume 2 (136 páginas; formato 18,2 cm x 25,6 cm; classificação indicativa: livre).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2023/07/manga-nausicaa-02-capa-150x213.jpg', 'https://editorajbc.com.br/mangas/colecao/nausicaa-do-vale-do-vento/vol/nausicaa-do-vale-do-vento-02/', '9786555943696', 'Ação e aventura|Ficção científica'),
    ('INK-3063', 'Neon Genesis Evangelion - Edição de Colecionador', 'Yoshiyuki Sadamoto e Hideaki Anno', 'Mangá', 'Vol. 2', 'Editora JBC', NULL, 'Shinji é chamado pelo pai para pilotar uma unidade Evangelion contra os Anjos. A defesa da cidade depende de adolescentes que conhecem pouco das máquinas e ainda menos dos planos dos adultos que os comandam. Edição brasileira da JBC, volume 2 (344 páginas; formato 15,0 × 21,0 cm; classificação indicativa: 16 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2023/03/evangelion-02-capa-150x210.jpg', 'https://editorajbc.com.br/mangas/colecao/neon-genesis-evangelion-edicao-de-colecionador/vol/neon-genesis-evangelion-collectors-edition-02/', '9786555944280', 'Ação e aventura|Drama|Ficção científica'),
    ('INK-3064', 'Não Chame de Mistério', 'Yumi Tamura', 'Mangá', 'Vol. 2', 'Editora JBC', NULL, 'Totono percebe contradições que passam despercebidas por quem investiga um crime. Suas conversas longas e pouco convencionais desmontam tanto álibis quanto certezas sobre o comportamento das vítimas. Edição brasileira da JBC, volume 2 (200 páginas; formato 13,2 × 20,0 cm; classificação indicativa: 16 anos).', 'https://editorajbc.com.br/wp-content/uploads/2024/06/nao-chame-de-misterio-02-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/nao-chame-de-misterio/vol/nao-chame-de-misterio-02/', '9786555946680', 'Ação e aventura|Comédia|Mistério e suspense'),
    ('INK-3065', 'Parasyte – Edição Especial Colorida', 'Hitoshi Iwaaki', 'Mangá', 'Vol. 2', 'Editora JBC', NULL, 'Um parasita falha ao tomar o cérebro de Shinichi e se instala em sua mão direita. Obrigados a compartilhar o corpo, rapaz e criatura enfrentam outros invasores sem concordar sequer sobre o valor de uma vida humana. Edição brasileira da JBC, volume 2 (288 páginas; formato 15,0 x 21,0 cm; classificação indicativa: 16 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2024/10/manga-parasyte-02-sobrecapa-150x210.jpg', 'https://editorajbc.com.br/mangas/colecao/parasyte-edicao-especial-colorida/vol/parasyte-edicao-especial-colorida-02/', '9786555947076', 'Ficção científica|Horror'),
    ('INK-3066', 'Sailor Moon Eternal Editon', 'Naoko Takeuchi', 'Mangá', 'Vol. 2', 'Editora JBC', NULL, 'Usagi descobre que pode se transformar em Sailor Moon. Reunir as demais guardiãs e proteger a Terra a aproxima de lembranças de outro reino que explicam por que a batalha chegou até ela. Edição brasileira da JBC, volume 2 (344 páginas; formato 15,2 × 21,0 cm; classificação indicativa: livre).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2025/06/sailor-moon-eternal-edition-02-sobrecapa-p-150x207.jpg', 'https://editorajbc.com.br/mangas/colecao/sailor-moon-eternal-editon/vol/sailor-moon-eternal-edition-02/', '9786555948080', 'Fantasia|Ação e aventura'),
    ('INK-3067', 'Saintia Shô', 'Chimaki Kuori', 'Mangá', 'Vol. 2', 'Editora JBC', NULL, 'Shoko entra em contato com as guerreiras que servem diretamente a Atena. A ameaça da deusa da discórdia transforma a procura pela irmã em uma batalha ligada ao destino do Santuário. Edição brasileira da JBC, volume 2 (184 páginas; formato 13,5 x 20,5 cm; classificação indicativa: 14 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2016/12/Saintia-Shô-02-Capa_p-150x229.jpg', 'https://editorajbc.com.br/mangas/colecao/saintia-sho/vol/saintia-sho-02/', '9788545702207', 'Ação e aventura|Fantasia'),
    ('INK-3068', 'Sangatsu no Lion - O Leão de Março', 'Chica Umino', 'Mangá', 'Vol. 2', 'Editora JBC', NULL, 'Rei Kiriyama joga shogi profissionalmente ainda adolescente e mora sozinho. As partidas revelam uma parte de sua história, enquanto a convivência com as irmãs Kawamoto abre espaço para uma vida além do tabuleiro. Edição brasileira da JBC, volume 2 (200 páginas; formato 13,2 × 20,0 cm; classificação indicativa: 16 anos).', 'https://editorajbc.com.br/wp-content/uploads/2023/03/sangatsu-no-lion-02-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/sangatsu-no-lion/vol/sangatsu-no-lion-o-leao-de-marco-02/', '9786555944105', 'Slice of life|Drama'),
    ('INK-3069', 'Shaman King BIG', 'Hiroyuki Takei', 'Mangá', 'Vol. 2', 'Editora JBC', NULL, 'Yoh Asakura vê espíritos e luta ao lado do samurai Amidamaru. Para disputar o título de Shaman King, terá de compreender o que move os outros médiuns a buscar tamanho poder. Edição brasileira da JBC, volume 2 (376 páginas; formato 15,0 × 21,0 cm; classificação indicativa: 14 anos).', 'https://editorajbc.com.br/wp-content/uploads/2021/09/shaman-king-big-02-sobrecapa-p-150x210.jpg', 'https://editorajbc.com.br/mangas/colecao/shaman-king-big/vol/shaman-king-big-02/', '9786555942187', 'Ação e aventura|Comédia'),
    ('INK-3070', 'Skip & Loafer', 'Misaki Takamatsu', 'Mangá', 'Vol. 2', 'Editora JBC', NULL, 'Mitsumi chega do interior para estudar em Tóquio com um plano de carreira detalhado. O primeiro dia já escapa do roteiro, e a amizade com Shima muda o que ela espera da escola e de si mesma. Edição brasileira da JBC, volume 2 (184 páginas; formato 12,8 × 18,2 cm; classificação indicativa: 12 anos).', 'https://editorajbc.com.br/wp-content/uploads/2024/10/skip-and-loafer-02-capa-150x210.jpg', 'https://editorajbc.com.br/mangas/colecao/skip-to-loafer/vol/skip-loafer-02/', '9786555947380', 'Drama'),
    ('INK-3071', 'Akane-Banashi', 'Yuki Suenaga e Takamasa Moue', 'Mangá', 'Vol. 3', 'Editora JBC', NULL, 'Akane quer conquistar seu lugar no rakugo, arte em que uma pessoa sentada diante da plateia interpreta todos os personagens de uma história. A expulsão do pai do meio profissional dá à sua ambição um motivo pessoal. Edição brasileira da JBC, volume 3 (200 páginas; formato 13,2 x 20,0 cm; classificação indicativa: 14 anos).', 'https://editorajbc.com.br/wp-content/uploads/2025/07/akane-banashi-03-capa-p-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/akane-banashi/vol/akane-banashi-03/', '9786555948554', 'Comédia|Drama'),
    ('INK-3072', 'Akira', 'Katsuhiro Otomo', 'Mangá', 'Vol. 3', 'Editora JBC', NULL, 'Em Neo-Tóquio, uma colisão durante uma corrida de motos põe Tetsuo sob custódia militar. Enquanto ele descobre um poder que mal consegue controlar, Kaneda acompanha o rastro de um segredo que a reconstrução da cidade tentou enterrar. Edição brasileira da JBC, volume 3 (288 páginas; formato 17,8 x 25,6 cm; classificação indicativa: 18 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2018/10/AKIRA-03-Sobrecapa_p-150x216.jpg', 'https://editorajbc.com.br/mangas/colecao/akira/vol/akira-03/', '9788545707226', 'Ficção científica'),
    ('INK-3073', 'Alice in Borderland', 'Haro Aso', 'Mangá', 'Vol. 3', 'Editora JBC', NULL, 'Arisu e os amigos encontram uma Tóquio estranhamente vazia. Para permanecer nela, precisam vencer jogos cujas cartas anunciam o tipo e a dificuldade da prova, mas escondem o preço de confiar na pessoa errada. Edição brasileira da JBC, volume 3 (320 páginas; formato 13,2 x 20,0 cm; classificação indicativa: 18 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2023/09/alice-in-borderland-big-03-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/alice-in-borderland/vol/alice-in-borderland-03/', '9786555945522', 'Ficção científica|Mistério e suspense'),
    ('INK-3074', 'Ao Ashi', 'Yugo Kobayashi', 'Mangá', 'Vol. 3', 'Editora JBC', NULL, 'Ashito Aoi chega ao futebol de base de Tóquio com instinto para ler o campo e pouca formação tática. Disputar espaço numa equipe profissional exige aprender a enxergar a jogada também pelos olhos dos companheiros. Edição brasileira da JBC, volume 3 (200 páginas; formato 13,2 × 20,0 cm; classificação indicativa: 14 anos).', 'https://editorajbc.com.br/wp-content/uploads/2023/05/ao-ashi-03-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/ao-ashi/vol/ao-ashi-craques-da-bola-03/', '9786555944440', 'Esportes'),
    ('INK-3075', 'Astro Boy', 'Osamu Tezuka', 'Mangá', 'Vol. 3', 'Editora JBC', NULL, 'Atom é um menino robô com força extraordinária num mundo em que humanos constroem máquinas à própria imagem. Cada aventura coloca em questão o que seus criadores devem às criaturas que aprenderam a pensar e a sentir. Edição brasileira da JBC, volume 3 (456 páginas; formato 15,0 x 21,0 cm; classificação indicativa: 14 anos).', 'https://editorajbc.com.br/wp-content/uploads/2025/07/astroboy-03-sobrecapa-p-150x210.jpg', 'https://editorajbc.com.br/mangas/colecao/astro-boy/vol/astro-boy-big-03/', '9786555948578', 'Ação e aventura|Ficção científica'),
    ('INK-3076', 'Bakuman', 'Tsugumi Ohba e Takeshi Obata', 'Mangá', 'Vol. 3', 'Editora JBC', NULL, 'Moritaka Mashiro desenha e Akito Takagi escreve. Decididos a publicar juntos, os colegas descobrem a distância entre uma boa ideia e uma série capaz de sobreviver a reuniões editoriais, prazos semanais e votações de leitores. Edição brasileira da JBC, volume 3 (200 páginas; formato 13,5 x 20,5 cm; classificação indicativa: livre).', 'https://editorajbc.com.br/wp-content/uploads/2011/10/manga-bakuman-03-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/bakuman/vol/bakuman-03/', '9786555945584', 'Comédia|Romance'),
    ('INK-3077', 'Blade - A Lâmina do Imortal - Nova Edição', 'Hiroaki Samura', 'Mangá', 'Vol. 3', 'Editora JBC', NULL, 'Rin procura os espadachins que destruíram sua família. Manji, um guerreiro cujos ferimentos se fecham sozinhos, aceita acompanhá-la. A jornada põe em dúvida quem decide qual morte merece vingança. Edição brasileira da JBC, volume 3 (464 páginas; formato 13,5 x 20,5 cm; classificação indicativa: 18 anos).', 'https://editorajbc.com.br/wp-content/uploads/2024/05/blade-03-capa-150x228.jpg', 'https://editorajbc.com.br/mangas/colecao/blade-a-lamina-do-imortal-nova-edicao/vol/blade-a-lamina-do-imortal-nova-edicao-03/', '9786555946475', 'Ação e aventura|Drama'),
    ('INK-3078', 'Blue Box', 'Kouji Miura', 'Mangá', 'Vol. 3', 'Editora JBC', NULL, 'Taiki chega cedo ao ginásio para treinar badminton e encontra Chinatsu, do basquete, praticando antes de todos. A convivência entre os atletas aproxima o primeiro amor da pressão por uma vaga nos campeonatos escolares. Edição brasileira da JBC, volume 3 (200 páginas; formato 13,2 x 20,0 cm; classificação indicativa: 10 anos).', 'https://editorajbc.com.br/wp-content/uploads/2024/12/blue-box-03-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/blue-box/vol/blue-box-03/', '9786555947717', 'Romance|Esportes'),
    ('INK-3079', 'Blue Exorcist', 'Kazue Katō', 'Mangá', 'Vol. 3', 'Editora JBC', NULL, 'Rin Okumura descobre uma ligação de sangue com o mundo que os exorcistas combatem. Ele escolhe treinar ao lado deles, embora revelar a origem de suas chamas possa custar a confiança dos colegas. Edição brasileira da JBC, volume 3 (208 páginas; formato 13,5 x 20,5 cm; classificação indicativa: 14 anos).', 'https://editorajbc.com.br/wp-content/uploads/2025/03/blue-exorcist-03-capa-20251-150x228.jpg', 'https://editorajbc.com.br/mangas/colecao/blue-exorcist/vol/blue-exorcist-03-2/', '9786555948370', 'Ação e aventura|Drama|Fantasia'),
    ('INK-3080', 'Boa Noite Punpun', 'Inio Asano', 'Mangá', 'Vol. 3', 'Editora JBC', NULL, 'Punpun atravessa infância, adolescência e vida adulta representado como um pequeno pássaro num cenário realista. As promessas feitas a Aiko acompanham o personagem enquanto os adultos ao redor dele também perdem o rumo. Edição brasileira da JBC, volume 3 (448 páginas; formato 13,2 cm x 20 cm; classificação indicativa: 18 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2019/03/Boa-Noite-Punpun-03-Capa_p-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/boa-noite-punpun/vol/boa-noite-punpun-03/', '9788545710608', 'Drama'),
    ('INK-3081', 'Boys Run the Riot', 'Keito Gaku', 'Mangá', 'Vol. 3', 'Editora JBC', NULL, 'Ryo encontra na roupa uma maneira de expressar quem é fora das expectativas da escola. A amizade com Jin transforma o interesse por moda no projeto de criar uma marca própria. Edição brasileira da JBC, volume 3 (192 páginas; formato 13,2 × 20,0 cm; classificação indicativa: 16 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2023/02/manga-boys-run-the-riot-03-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/boys-run-the-riot/vol/boys-run-the-riot-03/', '9786555944297', 'LGBTQIAPN+|Drama'),
    ('INK-3082', 'CDZ - Next Dimension', 'Masami Kurumada', 'Mangá', 'Vol. 3', 'Editora JBC', NULL, 'Para tentar salvar Seiya, Atena e seus companheiros voltam ao tempo da guerra sagrada anterior. No Santuário de outra época, rostos desconhecidos ocupam as armaduras que os heróis julgavam conhecer. Edição brasileira da JBC, volume 3 (152 páginas; formato 13,5 x 20,0 cm; classificação indicativa: 14 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2016/02/capa_cdz_next_dimension_a_saga_de_hades_03_g-150x222.jpg', 'https://editorajbc.com.br/mangas/colecao/cdz-next-dimension/vol/cdz-next-dimension-a-saga-de-hades-03/', '9788577874491', 'Ação e aventura|Fantasia'),
    ('INK-3083', 'CDZ - The Lost Canvas Gaiden ESPECIAL', 'Masami Kurumada e Shiori Teshirogi', 'Mangá', 'Vol. 3', 'Editora JBC', NULL, 'As histórias acompanham os Cavaleiros de Ouro da geração de Lost Canvas em missões próprias. Longe do centro da guerra contra Hades, cada guerreiro revela o custo pessoal de proteger sua casa zodiacal. Edição brasileira da JBC, volume 3 (200 páginas; formato 13,2 x 20,0 cm; classificação indicativa: 14 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2023/01/manga-lost-canvas-gaiden-03-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/cdz-the-lost-canvas-gaiden-esp/vol/cdz-the-lost-canvas-gaiden-esp-03/', '9788577875788', ''),
    ('INK-3084', 'CDZ Saint Seiya - Final Edition', 'Masami Kurumada', 'Mangá', 'Vol. 3', 'Editora JBC', NULL, 'Seiya conquista a Armadura de Pégaso e retorna ao Japão em busca da irmã. Seu caminho se cruza com o dos jovens cavaleiros que arriscam a vida para defender Atena. Edição brasileira da JBC, volume 3 (280 páginas; formato 13,2 × 20,0 cm; classificação indicativa: 14 anos).', 'https://editorajbc.com.br/wp-content/uploads/2025/04/cdz-final-edition-03-capa-mdg-150x222.jpg', 'https://editorajbc.com.br/mangas/colecao/saint-seiya-final-edition/vol/cavaleiros-do-zodiaco-saint-seiya-final-edition-03/', '9786555948523', 'Ação e aventura'),
    ('INK-3085', 'Cardcaptor Sakura Clear Card Arc', 'CLAMP', 'Mangá', 'Vol. 3', 'Editora JBC', NULL, 'Ao começar uma nova etapa na escola, Sakura percebe que as cartas que reuniu se tornaram transparentes. Sonhos enigmáticos e novos fenômenos mágicos levam a garota a investigar o que aconteceu com seus poderes. Edição brasileira da JBC, volume 3 (168 páginas; formato 13,2 x 20 cm; classificação indicativa: 10 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2019/11/Cardcaptor-Sakura-Clear-Card-Arc-03-Sobrecapa_p-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/cardcaptor-sakura-clear-card-arc/vol/cardcaptor-sakura-clear-card-arc-03/', '9788545713036', 'Fantasia'),
    ('INK-3086', 'Chi''s Sweet Home', 'Kanata Konami', 'Mangá', 'Vol. 3', 'Editora JBC', NULL, 'Uma gatinha se perde da mãe e encontra abrigo na casa da família Yamada. Do ponto de vista de Chi, uma porta fechada, a caixa de areia e a chegada de um visitante viram grandes acontecimentos. Edição brasileira da JBC, volume 3 (152 páginas; formato 17,0 x 24,0 cm; classificação indicativa: livre).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2021/09/chis-sweet-home-03-sobrecapa-p-150x209.jpg', 'https://editorajbc.com.br/mangas/colecao/chis-sweet-home/vol/chis-sweet-home-03/', '9786555941791', 'Comédia'),
    ('INK-3087', 'Dragon Quest - The Adventure of Dai', 'Riku Sanjo e Koji Inada', 'Mangá', 'Vol. 3', 'Editora JBC', NULL, 'Criado numa ilha habitada por monstros, Dai sonha com as façanhas dos heróis. O retorno das forças do mal põe sua coragem à prova e o obriga a sair da ilha para defender o mundo que mal conhece. Edição brasileira da JBC, volume 3 (344 páginas; formato 14,6 x 21,0 cm; classificação indicativa: 10 anos).', 'https://editorajbc.com.br/wp-content/uploads/2026/08/dragon-quest-dai-3-capa-150x216.jpg', 'https://editorajbc.com.br/mangas/colecao/dragon-quest-as-aventuras-de-dai/vol/dragon-quest-the-adventure-of-dai-03/', '9788545717874', 'Ação e aventura|Fantasia'),
    ('INK-3088', 'Final Fantasy - Lost Stranger', 'Hazuki Minase e Itsuki Kameya', 'Mangá', 'Vol. 3', 'Editora JBC', NULL, 'Dois irmãos são transportados para um mundo que reconhecem dos jogos de Final Fantasy. O conhecimento das regras parece uma vantagem até que uma perda torna urgente descobrir se a magia de ressurreição realmente existe. Edição brasileira da JBC, volume 3 (224 páginas; formato 13,2 × 20,0 cm; classificação indicativa: 14 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2022/09/manga-final-fantasy-lost-stranger-03-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/final-fantasy-lost-stranger/vol/final-fantasy-lost-stranger-03/', '9786555943382', 'Fantasia|Ficção científica'),
    ('INK-3089', 'Flying Witch', 'Chihiro Ishizuka', 'Mangá', 'Vol. 3', 'Editora JBC', NULL, 'Makoto vai morar com parentes no interior para se formar como bruxa. Entre a horta, a escola e as visitas de seres sobrenaturais, aprender magia também significa aprender os ritmos da nova casa. Edição brasileira da JBC, volume 3 (168 páginas; formato 13,2 × 20,0 cm; classificação indicativa: livre).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2023/12/manga-flying-witch-03-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/flying-witch/vol/flying-witch-03/', '9786555945768', 'Fantasia|Comédia|Slice of life'),
    ('INK-3090', 'Fênix', 'Osamu Tezuka', 'Mangá', 'Vol. 3', 'Editora JBC', NULL, 'Osamu Tezuka alterna épocas remotas e futuros distantes para acompanhar pessoas que perseguem a ave de fogo. A promessa de vencer a morte expõe desejos que se repetem mesmo quando as civilizações desaparecem. Edição brasileira da JBC, volume 3 (688 páginas; formato 15,0 x 21,0 cm; classificação indicativa: 14 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2024/10/fenix-03-sobrecapa-150x210.jpg', 'https://editorajbc.com.br/mangas/colecao/fenix/vol/fenix-03/', '9786555946956', 'Drama|Fantasia'),
    ('INK-3091', 'Haikyu!!', 'Haruichi Furudate', 'Mangá', 'Vol. 3', 'Editora JBC', NULL, 'Hinata quer voar sobre a rede apesar da baixa estatura. Ao entrar no time de vôlei do Karasuno, precisa aprender a jogar com Kageyama, o levantador que antes o derrotou e que agora pode aproveitar melhor sua velocidade. Edição brasileira da JBC, volume 3 (392 páginas; formato 13,2 × 20,0 cm; classificação indicativa: livre).', 'https://editorajbc.com.br/wp-content/uploads/2022/01/haikyu-big-03-capa-p-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/haikyu/vol/haikyu-03/', '9786555942477', 'Esportes|Comédia|Drama'),
    ('INK-3092', 'Hellsing ESP.', 'Kouta Hirano', 'Mangá', 'Vol. 3', 'Editora JBC', NULL, 'A organização Hellsing protege a Inglaterra de ameaças sobrenaturais com a ajuda de Alucard, um vampiro a seu serviço. A policial Seras Victoria entra nesse mundo e precisa descobrir o que ainda significa agir como humana. Edição brasileira da JBC, volume 3 (208 páginas; formato 13,5 x 20,5 cm; classificação indicativa: 18 anos).', 'https://editorajbc.com.br/wp-content/uploads/2025/09/hellsing-03-capa-2025-p-150x228.jpg', 'https://editorajbc.com.br/mangas/colecao/hellsing-esp/vol/hellsing-especial-03/', '9786555949834', 'Ação e aventura'),
    ('INK-3093', 'InuYasha Wideban', 'Rumiko Takahashi', 'Mangá', 'Vol. 3', 'Editora JBC', NULL, 'Kagome atravessa um poço que liga sua casa ao Japão feudal. Ao lado de Inuyasha, procura os fragmentos de uma joia cobiçada por humanos e demônios, enquanto aprende a viver entre duas épocas. Edição brasileira da JBC, volume 3 (337 páginas; formato 12,8 x 18,2 cm; classificação indicativa: 14 anos).', 'https://editorajbc.com.br/wp-content/uploads/2022/04/inuyasha-wideban-03-sobrecapa-p-150x213.jpg', 'https://editorajbc.com.br/mangas/colecao/inuyasha-wideban/vol/inuyasha-wideban-03/', '9786555942996', ''),
    ('INK-3094', 'Kamen Rider Kuuga BIG', 'Toshiki Inoue , Hitotsu Yokoshima e Shotaro Ishinomori', 'Mangá', 'Vol. 3', 'Editora JBC', NULL, 'O despertar de seres antigos transforma investigações policiais em uma corrida contra mortes inexplicáveis. Um poder ligado às ruínas dá a um jovem a capacidade de enfrentar os inimigos sob a forma de Kuuga. Edição brasileira da JBC, volume 3 (384 páginas; formato 13,2 × 20,0 cm; classificação indicativa: 16 anos).', 'https://editorajbc.com.br/wp-content/uploads/2022/06/kamen-rider-kuuga-03-capa-p-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/kamen-rider-kuuga-big/vol/kamen-rider-kuuga-big-03/', '9786555943061', 'Ação e aventura'),
    ('INK-3095', 'Medalist', 'Tsuruma Ikada', 'Mangá', 'Vol. 3', 'Editora JBC', NULL, 'Inori quer competir na patinação artística e encontra em Tsukasa um treinador disposto a apostar nela. Saltos e programas ganham peso numa modalidade em que começar tarde já é tratado como desvantagem. Edição brasileira da JBC, volume 3 (200 páginas; formato 13,2 × 20,0 cm; classificação indicativa: livre).', 'https://editorajbc.com.br/wp-content/uploads/2026/03/br-medalist-03-cover-1-copiar-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/medalist/vol/medalist-03/', '9788545717041', 'Drama|Esportes'),
    ('INK-3096', 'My Home Hero', 'Naoki Yamakawa e Masashi Asaki', 'Mangá', 'Vol. 3', 'Editora JBC', NULL, 'Ao tentar proteger a filha de um relacionamento violento, um pai de família atrai a atenção do crime organizado. Seu repertório de romances policiais deixa de ser passatempo quando ele precisa sustentar a própria versão dos acontecimentos. Edição brasileira da JBC, volume 3 (192 páginas; formato 13,2 × 20,0 cm; classificação indicativa: 18 anos).', 'https://editorajbc.com.br/wp-content/uploads/2024/09/my-home-hero-03-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/my-home-hero/vol/my-home-hero-03/', '9786555946758', 'Drama|Mistério e suspense'),
    ('INK-3097', 'Nausicaä do Vale do Vento', 'Hayao Miyazaki', 'Mangá', 'Vol. 3', 'Editora JBC', NULL, 'Nausicaä explora uma floresta tóxica que avança sobre o território humano. Quando reinos vizinhos entram em guerra, compreender os insetos e o solo pode ser mais importante para o Vale do Vento do que vencer uma batalha. Edição brasileira da JBC, volume 3 (148 páginas; formato 18,2 cm x 25,6 cm; classificação indicativa: livre).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2023/07/manga-nausicaa-03-capa-150x213.jpg', 'https://editorajbc.com.br/mangas/colecao/nausicaa-do-vale-do-vento/vol/nausicaa-do-vale-do-vento-03/', '9786555945096', 'Ação e aventura|Ficção científica'),
    ('INK-3098', 'Neon Genesis Evangelion - Edição de Colecionador', 'Yoshiyuki Sadamoto e Hideaki Anno', 'Mangá', 'Vol. 3', 'Editora JBC', NULL, 'Shinji é chamado pelo pai para pilotar uma unidade Evangelion contra os Anjos. A defesa da cidade depende de adolescentes que conhecem pouco das máquinas e ainda menos dos planos dos adultos que os comandam. Edição brasileira da JBC, volume 3 (376 páginas; formato 15,0 × 21,0 cm; classificação indicativa: 16 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2023/10/evangelion-03-sobrecapa-150x210.jpg', 'https://editorajbc.com.br/mangas/colecao/neon-genesis-evangelion-edicao-de-colecionador/vol/neon-genesis-evangelion-collectors-edition-03/', '9786555944563', 'Ação e aventura|Drama|Ficção científica'),
    ('INK-3099', 'Não Chame de Mistério', 'Yumi Tamura', 'Mangá', 'Vol. 3', 'Editora JBC', NULL, 'Totono percebe contradições que passam despercebidas por quem investiga um crime. Suas conversas longas e pouco convencionais desmontam tanto álibis quanto certezas sobre o comportamento das vítimas. Edição brasileira da JBC, volume 3 (200 páginas; formato 13,2 × 20,0 cm; classificação indicativa: 16 anos).', 'https://editorajbc.com.br/wp-content/uploads/2024/10/nao-chame-de-misterio-03-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/nao-chame-de-misterio/vol/nao-chame-de-misterio-03/', '9786555946987', 'Ação e aventura|Comédia|Mistério e suspense'),
    ('INK-3100', 'Parasyte – Edição Especial Colorida', 'Hitoshi Iwaaki', 'Mangá', 'Vol. 3', 'Editora JBC', NULL, 'Um parasita falha ao tomar o cérebro de Shinichi e se instala em sua mão direita. Obrigados a compartilhar o corpo, rapaz e criatura enfrentam outros invasores sem concordar sequer sobre o valor de uma vida humana. Edição brasileira da JBC, volume 3 (288 páginas; formato 15,0 x 21,0 cm; classificação indicativa: 16 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2025/01/parasyte-03-sobrecapa-150x210.jpg', 'https://editorajbc.com.br/mangas/colecao/parasyte-edicao-especial-colorida/vol/parasyte-edicao-especial-colorida-03/', '9786555947847', 'Ficção científica|Horror'),
    ('INK-3101', 'Sailor Moon Eternal Editon', 'Naoko Takeuchi', 'Mangá', 'Vol. 3', 'Editora JBC', NULL, 'Usagi descobre que pode se transformar em Sailor Moon. Reunir as demais guardiãs e proteger a Terra a aproxima de lembranças de outro reino que explicam por que a batalha chegou até ela. Edição brasileira da JBC, volume 3 (344 páginas; formato 15,2 × 21,0 cm; classificação indicativa: livre).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2025/09/sailor-moon-eternal-edition-03-capa-p-150x207.jpg', 'https://editorajbc.com.br/mangas/colecao/sailor-moon-eternal-editon/vol/sailor-moon-eternal-edition-03/', '9786555949742', 'Fantasia|Ação e aventura'),
    ('INK-3102', 'Saintia Shô', 'Chimaki Kuori', 'Mangá', 'Vol. 3', 'Editora JBC', NULL, 'Shoko entra em contato com as guerreiras que servem diretamente a Atena. A ameaça da deusa da discórdia transforma a procura pela irmã em uma batalha ligada ao destino do Santuário. Edição brasileira da JBC, volume 3 (184 páginas; formato 13,5 x 20,5 cm; classificação indicativa: 14 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2017/02/Saintia-Shô-03-Capa_p-150x228.jpg', 'https://editorajbc.com.br/mangas/colecao/saintia-sho/vol/saintia-sho-03/', '9788545702450', 'Ação e aventura|Fantasia'),
    ('INK-3103', 'Sangatsu no Lion - O Leão de Março', 'Chica Umino', 'Mangá', 'Vol. 3', 'Editora JBC', NULL, 'Rei Kiriyama joga shogi profissionalmente ainda adolescente e mora sozinho. As partidas revelam uma parte de sua história, enquanto a convivência com as irmãs Kawamoto abre espaço para uma vida além do tabuleiro. Edição brasileira da JBC, volume 3 (192 páginas; formato 13,2 × 20,0 cm; classificação indicativa: 16 anos).', 'https://editorajbc.com.br/wp-content/uploads/2023/06/manga-sangatsu-03-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/sangatsu-no-lion/vol/sangatsu-no-lion-o-leao-de-marco-03/', '9786555944174', 'Slice of life|Drama'),
    ('INK-3104', 'Shaman King BIG', 'Hiroyuki Takei', 'Mangá', 'Vol. 3', 'Editora JBC', NULL, 'Yoh Asakura vê espíritos e luta ao lado do samurai Amidamaru. Para disputar o título de Shaman King, terá de compreender o que move os outros médiuns a buscar tamanho poder. Edição brasileira da JBC, volume 3 (376 páginas; formato 15,0 × 21,0 cm; classificação indicativa: 14 anos).', 'https://editorajbc.com.br/wp-content/uploads/2022/04/shaman-king-big-03-sobrecapa-p-150x210.jpg', 'https://editorajbc.com.br/mangas/colecao/shaman-king-big/vol/shaman-king-big-03/', '9786555943009', 'Ação e aventura|Comédia'),
    ('INK-3105', 'Skip & Loafer', 'Misaki Takamatsu', 'Mangá', 'Vol. 3', 'Editora JBC', NULL, 'Mitsumi chega do interior para estudar em Tóquio com um plano de carreira detalhado. O primeiro dia já escapa do roteiro, e a amizade com Shima muda o que ela espera da escola e de si mesma. Edição brasileira da JBC, volume 3 (184 páginas; formato 12,8 × 18,2 cm; classificação indicativa: 12 anos).', 'https://editorajbc.com.br/wp-content/uploads/2024/12/skip-and-loafer-03-capa-150x210.jpg', 'https://editorajbc.com.br/mangas/colecao/skip-to-loafer/vol/skip-loafer-03/', '9786555947793', 'Drama'),
    ('INK-3106', 'Akane-Banashi', 'Yuki Suenaga e Takamasa Moue', 'Mangá', 'Vol. 4', 'Editora JBC', NULL, 'Akane quer conquistar seu lugar no rakugo, arte em que uma pessoa sentada diante da plateia interpreta todos os personagens de uma história. A expulsão do pai do meio profissional dá à sua ambição um motivo pessoal. Edição brasileira da JBC, volume 4 (200 páginas; formato 13,2 x 20,0 cm; classificação indicativa: 14 anos).', 'https://editorajbc.com.br/wp-content/uploads/2025/07/akane-banashi-04-capa-p-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/akane-banashi/vol/akane-banashi-04/', '9786555949407', 'Comédia|Drama'),
    ('INK-3107', 'Akira', 'Katsuhiro Otomo', 'Mangá', 'Vol. 4', 'Editora JBC', NULL, 'Em Neo-Tóquio, uma colisão durante uma corrida de motos põe Tetsuo sob custódia militar. Enquanto ele descobre um poder que mal consegue controlar, Kaneda acompanha o rastro de um segredo que a reconstrução da cidade tentou enterrar. Edição brasileira da JBC, volume 4 (400 páginas; formato 17,8 x 25,6 cm; classificação indicativa: 18 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2019/07/AKIRA-04-Sobrecapa_p-150x216.jpg', 'https://editorajbc.com.br/mangas/colecao/akira/vol/akira-04/', '9788545711513', 'Ficção científica'),
    ('INK-3108', 'Alice in Borderland', 'Haro Aso', 'Mangá', 'Vol. 4', 'Editora JBC', NULL, 'Arisu e os amigos encontram uma Tóquio estranhamente vazia. Para permanecer nela, precisam vencer jogos cujas cartas anunciam o tipo e a dificuldade da prova, mas escondem o preço de confiar na pessoa errada. Edição brasileira da JBC, volume 4 (336 páginas; formato 13,2 x 20,0 cm; classificação indicativa: 18 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2024/09/alice-in-borderland-big-04-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/alice-in-borderland/vol/alice-in-borderland-04/', '9786555946796', 'Ficção científica|Mistério e suspense'),
    ('INK-3109', 'Ao Ashi', 'Yugo Kobayashi', 'Mangá', 'Vol. 4', 'Editora JBC', NULL, 'Ashito Aoi chega ao futebol de base de Tóquio com instinto para ler o campo e pouca formação tática. Disputar espaço numa equipe profissional exige aprender a enxergar a jogada também pelos olhos dos companheiros. Edição brasileira da JBC, volume 4 (216 páginas; formato 13,2 × 20,0 cm; classificação indicativa: 14 anos).', 'https://editorajbc.com.br/wp-content/uploads/2023/07/manga-ao-ashi-04-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/ao-ashi/vol/ao-ashi-craques-da-bola-04/', '9786555944853', 'Esportes'),
    ('INK-3110', 'Astro Boy', 'Osamu Tezuka', 'Mangá', 'Vol. 4', 'Editora JBC', NULL, 'Atom é um menino robô com força extraordinária num mundo em que humanos constroem máquinas à própria imagem. Cada aventura coloca em questão o que seus criadores devem às criaturas que aprenderam a pensar e a sentir. Edição brasileira da JBC, volume 4 (464 páginas; formato 15,0 x 21,0 cm; classificação indicativa: 14 anos).', 'https://editorajbc.com.br/wp-content/uploads/2026/01/astroboy-04-sobrecapa-p-150x209.jpg', 'https://editorajbc.com.br/mangas/colecao/astro-boy/vol/astro-boy-big-04/', '9786555949964', 'Ação e aventura|Ficção científica'),
    ('INK-3111', 'Bakuman', 'Tsugumi Ohba e Takeshi Obata', 'Mangá', 'Vol. 4', 'Editora JBC', NULL, 'Moritaka Mashiro desenha e Akito Takagi escreve. Decididos a publicar juntos, os colegas descobrem a distância entre uma boa ideia e uma série capaz de sobreviver a reuniões editoriais, prazos semanais e votações de leitores. Edição brasileira da JBC, volume 4 (200 páginas; formato 13,5 x 20,5 cm; classificação indicativa: livre).', 'https://editorajbc.com.br/wp-content/uploads/2011/11/manga-bakuman-04-capa-150x229.jpg', 'https://editorajbc.com.br/mangas/colecao/bakuman/vol/bakuman-04-2/', '9786555946062', 'Comédia|Romance'),
    ('INK-3112', 'Blade - A Lâmina do Imortal - Nova Edição', 'Hiroaki Samura', 'Mangá', 'Vol. 4', 'Editora JBC', NULL, 'Rin procura os espadachins que destruíram sua família. Manji, um guerreiro cujos ferimentos se fecham sozinhos, aceita acompanhá-la. A jornada põe em dúvida quem decide qual morte merece vingança. Edição brasileira da JBC, volume 4 (480 páginas; formato 13,5 x 20,5 cm; classificação indicativa: 18 anos).', 'https://editorajbc.com.br/wp-content/uploads/2024/10/blade-04-capa-150x228.jpg', 'https://editorajbc.com.br/mangas/colecao/blade-a-lamina-do-imortal-nova-edicao/vol/blade-a-lamina-do-imortal-nova-edicao-04/', '9786555946888', 'Ação e aventura|Drama'),
    ('INK-3113', 'Blue Box', 'Kouji Miura', 'Mangá', 'Vol. 4', 'Editora JBC', NULL, 'Taiki chega cedo ao ginásio para treinar badminton e encontra Chinatsu, do basquete, praticando antes de todos. A convivência entre os atletas aproxima o primeiro amor da pressão por uma vaga nos campeonatos escolares. Edição brasileira da JBC, volume 4 (192 páginas; formato 13,2 x 20,0 cm; classificação indicativa: 10 anos).', 'https://editorajbc.com.br/wp-content/uploads/2025/03/blue-box-04-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/blue-box/vol/blue-box-04/', '9786555947946', 'Romance|Esportes'),
    ('INK-3114', 'Blue Exorcist', 'Kazue Katō', 'Mangá', 'Vol. 4', 'Editora JBC', NULL, 'Rin Okumura descobre uma ligação de sangue com o mundo que os exorcistas combatem. Ele escolhe treinar ao lado deles, embora revelar a origem de suas chamas possa custar a confiança dos colegas. Edição brasileira da JBC, volume 4 (208 páginas; formato 13,5 x 20,5 cm; classificação indicativa: 14 anos).', 'https://editorajbc.com.br/wp-content/uploads/2025/03/blue-exorcist-04-capa-2025-150x228.jpg', 'https://editorajbc.com.br/mangas/colecao/blue-exorcist/vol/blue-exorcist-04-2/', '9786555948387', 'Ação e aventura|Drama|Fantasia'),
    ('INK-3115', 'Boa Noite Punpun', 'Inio Asano', 'Mangá', 'Vol. 4', 'Editora JBC', NULL, 'Punpun atravessa infância, adolescência e vida adulta representado como um pequeno pássaro num cenário realista. As promessas feitas a Aiko acompanham o personagem enquanto os adultos ao redor dele também perdem o rumo. Edição brasileira da JBC, volume 4 (456 páginas; formato 13,2 cm x 20 cm; classificação indicativa: 18 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2019/03/Boa-Noite-Punpun-04-Capa_p-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/boa-noite-punpun/vol/boa-noite-punpun-04/', '9788545710615', 'Drama'),
    ('INK-3116', 'Boys Run the Riot', 'Keito Gaku', 'Mangá', 'Vol. 4', 'Editora JBC', NULL, 'Ryo encontra na roupa uma maneira de expressar quem é fora das expectativas da escola. A amizade com Jin transforma o interesse por moda no projeto de criar uma marca própria. Edição brasileira da JBC, volume 4 (208 páginas; formato 13,2 × 20,0 cm; classificação indicativa: 16 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2023/05/manga-boys-run-the-riot-04-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/boys-run-the-riot/vol/boys-run-the-riot-04/', '9786555944532', 'LGBTQIAPN+|Drama'),
    ('INK-3117', 'CDZ - Next Dimension', 'Masami Kurumada', 'Mangá', 'Vol. 4', 'Editora JBC', NULL, 'Para tentar salvar Seiya, Atena e seus companheiros voltam ao tempo da guerra sagrada anterior. No Santuário de outra época, rostos desconhecidos ocupam as armaduras que os heróis julgavam conhecer. Edição brasileira da JBC, volume 4 (152 páginas; formato 13,5 x 20,0 cm; classificação indicativa: 14 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2016/02/capa_cdz_next_dimension_a_saga_de_hades_04_g-150x222.jpg', 'https://editorajbc.com.br/mangas/colecao/cdz-next-dimension/vol/cdz-next-dimension-a-saga-de-hades-04/', '9788577875399', 'Ação e aventura|Fantasia'),
    ('INK-3118', 'CDZ - The Lost Canvas Gaiden ESPECIAL', 'Masami Kurumada e Shiori Teshirogi', 'Mangá', 'Vol. 4', 'Editora JBC', NULL, 'As histórias acompanham os Cavaleiros de Ouro da geração de Lost Canvas em missões próprias. Longe do centro da guerra contra Hades, cada guerreiro revela o custo pessoal de proteger sua casa zodiacal. Edição brasileira da JBC, volume 4 (192 páginas; formato 13,2 x 20,0 cm; classificação indicativa: 14 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2023/01/manga-lost-canvas-gaiden-04-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/cdz-the-lost-canvas-gaiden-esp/vol/cdz-the-lost-canvas-gaiden-esp-04/', '9788577875979', ''),
    ('INK-3119', 'CDZ Saint Seiya - Final Edition', 'Masami Kurumada', 'Mangá', 'Vol. 4', 'Editora JBC', NULL, 'Seiya conquista a Armadura de Pégaso e retorna ao Japão em busca da irmã. Seu caminho se cruza com o dos jovens cavaleiros que arriscam a vida para defender Atena. Edição brasileira da JBC, volume 4 (288 páginas; formato 13,2 × 20,0 cm; classificação indicativa: 14 anos).', 'https://editorajbc.com.br/wp-content/uploads/2025/07/cdz-final-edition-04-capa-mdg-p-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/saint-seiya-final-edition/vol/cavaleiros-do-zodiaco-saint-seiya-final-edition-04/', '9786555949261', 'Ação e aventura'),
    ('INK-3120', 'Cardcaptor Sakura Clear Card Arc', 'CLAMP', 'Mangá', 'Vol. 4', 'Editora JBC', NULL, 'Ao começar uma nova etapa na escola, Sakura percebe que as cartas que reuniu se tornaram transparentes. Sonhos enigmáticos e novos fenômenos mágicos levam a garota a investigar o que aconteceu com seus poderes. Edição brasileira da JBC, volume 4 (160 páginas; formato 13,2 x 20 cm; classificação indicativa: 10 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2019/12/Cardcaptor-Sakura-Clear-Card-Arc-04-Sobrecapa_p-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/cardcaptor-sakura-clear-card-arc/vol/cardcaptor-sakura-clear-card-arc-04/', '9788545713043', 'Fantasia'),
    ('INK-3121', 'Chi''s Sweet Home', 'Kanata Konami', 'Mangá', 'Vol. 4', 'Editora JBC', NULL, 'Uma gatinha se perde da mãe e encontra abrigo na casa da família Yamada. Do ponto de vista de Chi, uma porta fechada, a caixa de areia e a chegada de um visitante viram grandes acontecimentos. Edição brasileira da JBC, volume 4 (152 páginas; formato 17,0 x 24,0 cm; classificação indicativa: livre).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2022/01/chis-sweet-home-04-sobrecapa-p-150x209.jpg', 'https://editorajbc.com.br/mangas/colecao/chis-sweet-home/vol/chis-sweet-home-04/', '9786555942576', 'Comédia'),
    ('INK-3122', 'Dragon Quest - The Adventure of Dai', 'Riku Sanjo e Koji Inada', 'Mangá', 'Vol. 4', 'Editora JBC', NULL, 'Criado numa ilha habitada por monstros, Dai sonha com as façanhas dos heróis. O retorno das forças do mal põe sua coragem à prova e o obriga a sair da ilha para defender o mundo que mal conhece. Edição brasileira da JBC, volume 4 (344 páginas; formato 14,6 x 21,0 cm; classificação indicativa: 10 anos).', 'https://editorajbc.com.br/wp-content/uploads/2026/10/ja19151-dragon-quest-dai-4-capa-p-150x216.jpg', 'https://editorajbc.com.br/mangas/colecao/dragon-quest-as-aventuras-de-dai/vol/dragon-quest-the-adventure-of-dai-04/', '9788545719151', 'Ação e aventura|Fantasia'),
    ('INK-3123', 'Final Fantasy - Lost Stranger', 'Hazuki Minase e Itsuki Kameya', 'Mangá', 'Vol. 4', 'Editora JBC', NULL, 'Dois irmãos são transportados para um mundo que reconhecem dos jogos de Final Fantasy. O conhecimento das regras parece uma vantagem até que uma perda torna urgente descobrir se a magia de ressurreição realmente existe. Edição brasileira da JBC, volume 4 (208 páginas; formato 13,2 x 20,0 cm; classificação indicativa: 14 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2023/01/manga-final-fantasy-lost-stranger-04-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/final-fantasy-lost-stranger/vol/final-fantasy-lost-stranger-04/', '9786555943771', 'Fantasia|Ficção científica'),
    ('INK-3124', 'Flying Witch', 'Chihiro Ishizuka', 'Mangá', 'Vol. 4', 'Editora JBC', NULL, 'Makoto vai morar com parentes no interior para se formar como bruxa. Entre a horta, a escola e as visitas de seres sobrenaturais, aprender magia também significa aprender os ritmos da nova casa. Edição brasileira da JBC, volume 4 (168 páginas; formato 13,2 × 20,0 cm; classificação indicativa: livre).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2024/02/flying-witch-04-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/flying-witch/vol/flying-witch-04/', '9786555946079', 'Fantasia|Comédia|Slice of life'),
    ('INK-3125', 'Fullmetal Alchemist ESPECIAL', 'Hiromu Arakawa', 'Mangá', 'Vol. 4', 'Editora JBC', NULL, 'Edward perdeu membros e Alphonse perdeu o corpo numa tentativa de trazer a mãe de volta pela alquimia. A procura por uma forma de reparar o erro leva os irmãos a laboratórios e quartéis onde a troca equivalente tem consequências humanas. Edição brasileira da JBC, volume 4 (200 páginas; formato 13,5 x 20,5 cm; classificação indicativa: 14 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2016/09/FMA-Esp_04_p-150x228.jpg', 'https://editorajbc.com.br/mangas/colecao/fullmetal-alchemist-especial/vol/fullmetal-alchemist-esp-04/', '9788545702184', 'Ação e aventura|Comédia|Drama|Fantasia|Ficção científica'),
    ('INK-3126', 'Fênix', 'Osamu Tezuka', 'Mangá', 'Vol. 4', 'Editora JBC', NULL, 'Osamu Tezuka alterna épocas remotas e futuros distantes para acompanhar pessoas que perseguem a ave de fogo. A promessa de vencer a morte expõe desejos que se repetem mesmo quando as civilizações desaparecem. Edição brasileira da JBC, volume 4 (728 páginas; formato 15,0 x 21,0 cm; classificação indicativa: 14 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2025/05/fenix-04-sobrecapa-150x210.jpg', 'https://editorajbc.com.br/mangas/colecao/fenix/vol/fenix-04/', '9786555947960', 'Drama|Fantasia'),
    ('INK-3127', 'Haikyu!!', 'Haruichi Furudate', 'Mangá', 'Vol. 4', 'Editora JBC', NULL, 'Hinata quer voar sobre a rede apesar da baixa estatura. Ao entrar no time de vôlei do Karasuno, precisa aprender a jogar com Kageyama, o levantador que antes o derrotou e que agora pode aproveitar melhor sua velocidade. Edição brasileira da JBC, volume 4 (384 páginas; formato 13,2 × 20,0 cm; classificação indicativa: livre).', 'https://editorajbc.com.br/wp-content/uploads/2022/04/haikyu-big-04-capa-p-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/haikyu/vol/haikyu-04/', '9786555942958', 'Esportes|Comédia|Drama'),
    ('INK-3128', 'Hellsing ESP.', 'Kouta Hirano', 'Mangá', 'Vol. 4', 'Editora JBC', NULL, 'A organização Hellsing protege a Inglaterra de ameaças sobrenaturais com a ajuda de Alucard, um vampiro a seu serviço. A policial Seras Victoria entra nesse mundo e precisa descobrir o que ainda significa agir como humana. Edição brasileira da JBC, volume 4 (200 páginas; formato 13,5 x 20,5 cm; classificação indicativa: 18 anos).', 'https://editorajbc.com.br/wp-content/uploads/2015/09/capa_hellsing_esp_04_g-150x228.jpg', 'https://editorajbc.com.br/mangas/colecao/hellsing-esp/vol/hellsing-especial-04/', '9788545715252', 'Ação e aventura'),
    ('INK-3129', 'InuYasha Wideban', 'Rumiko Takahashi', 'Mangá', 'Vol. 4', 'Editora JBC', NULL, 'Kagome atravessa um poço que liga sua casa ao Japão feudal. Ao lado de Inuyasha, procura os fragmentos de uma joia cobiçada por humanos e demônios, enquanto aprende a viver entre duas épocas. Edição brasileira da JBC, volume 4 (353 páginas; formato 12,8 x 18,2 cm; classificação indicativa: 14 anos).', 'https://editorajbc.com.br/wp-content/uploads/2022/08/manga-inuyasha-wideban-04-capa-150x213.jpg', 'https://editorajbc.com.br/mangas/colecao/inuyasha-wideban/vol/inuyasha-wideban-04/', '9786555943337', ''),
    ('INK-3130', 'Kamen Rider Kuuga BIG', 'Toshiki Inoue , Hitotsu Yokoshima e Shotaro Ishinomori', 'Mangá', 'Vol. 4', 'Editora JBC', NULL, 'O despertar de seres antigos transforma investigações policiais em uma corrida contra mortes inexplicáveis. Um poder ligado às ruínas dá a um jovem a capacidade de enfrentar os inimigos sob a forma de Kuuga. Edição brasileira da JBC, volume 4 (440 páginas; formato 13,2 × 20,0 cm; classificação indicativa: 16 anos).', 'https://editorajbc.com.br/wp-content/uploads/2023/01/kamen-rider-kuuga-04-capa-p-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/kamen-rider-kuuga-big/vol/kamen-rider-kuuga-big-04/', '9786555943979', 'Ação e aventura'),
    ('INK-3131', 'Medalist', 'Tsuruma Ikada', 'Mangá', 'Vol. 4', 'Editora JBC', NULL, 'Inori quer competir na patinação artística e encontra em Tsukasa um treinador disposto a apostar nela. Saltos e programas ganham peso numa modalidade em que começar tarde já é tratado como desvantagem. Edição brasileira da JBC, volume 4 (200 páginas; formato 13,2 × 20,0 cm; classificação indicativa: livre).', 'https://editorajbc.com.br/wp-content/uploads/2026/06/medalist-4-capa-p-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/medalist/vol/medalist-04/', '9788545717652', 'Drama|Esportes'),
    ('INK-3132', 'My Home Hero', 'Naoki Yamakawa e Masashi Asaki', 'Mangá', 'Vol. 4', 'Editora JBC', NULL, 'Ao tentar proteger a filha de um relacionamento violento, um pai de família atrai a atenção do crime organizado. Seu repertório de romances policiais deixa de ser passatempo quando ele precisa sustentar a própria versão dos acontecimentos. Edição brasileira da JBC, volume 4 (192 páginas; formato 13,2 × 20,0 cm; classificação indicativa: 18 anos).', 'https://editorajbc.com.br/wp-content/uploads/2024/10/my-home-hero-04-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/my-home-hero/vol/my-home-hero-04/', '9786555947434', 'Drama|Mistério e suspense'),
    ('INK-3133', 'Nausicaä do Vale do Vento', 'Hayao Miyazaki', 'Mangá', 'Vol. 4', 'Editora JBC', NULL, 'Nausicaä explora uma floresta tóxica que avança sobre o território humano. Quando reinos vizinhos entram em guerra, compreender os insetos e o solo pode ser mais importante para o Vale do Vento do que vencer uma batalha. Edição brasileira da JBC, volume 4 (144 páginas; formato 18,2 x 25,6 cm; classificação indicativa: livre).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2024/10/nausicaa-04-capa-150x213.jpg', 'https://editorajbc.com.br/mangas/colecao/nausicaa-do-vale-do-vento/vol/nausicaa-do-vale-do-vento-04/', '9786555947205', 'Ação e aventura|Ficção científica'),
    ('INK-3134', 'Neon Genesis Evangelion - Edição de Colecionador', 'Yoshiyuki Sadamoto e Hideaki Anno', 'Mangá', 'Vol. 4', 'Editora JBC', NULL, 'Shinji é chamado pelo pai para pilotar uma unidade Evangelion contra os Anjos. A defesa da cidade depende de adolescentes que conhecem pouco das máquinas e ainda menos dos planos dos adultos que os comandam. Edição brasileira da JBC, volume 4 (368 páginas; formato 15,0 × 21,0 cm; classificação indicativa: 16 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2024/02/evangelion-04-sobrecapa-150x210.jpg', 'https://editorajbc.com.br/mangas/colecao/neon-genesis-evangelion-edicao-de-colecionador/vol/neon-genesis-evangelion-collectors-edition-04/', '9786555946086', 'Ação e aventura|Drama|Ficção científica'),
    ('INK-3135', 'Não Chame de Mistério', 'Yumi Tamura', 'Mangá', 'Vol. 4', 'Editora JBC', NULL, 'Totono percebe contradições que passam despercebidas por quem investiga um crime. Suas conversas longas e pouco convencionais desmontam tanto álibis quanto certezas sobre o comportamento das vítimas. Edição brasileira da JBC, volume 4 (200 páginas; formato 13,2 x 20,0 cm; classificação indicativa: 16 anos).', 'https://editorajbc.com.br/wp-content/uploads/2025/03/nao-chame-de-misterio-04-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/nao-chame-de-misterio/vol/nao-chame-de-misterio-04/', '9786555947854', 'Ação e aventura|Comédia|Mistério e suspense'),
    ('INK-3136', 'Parasyte – Edição Especial Colorida', 'Hitoshi Iwaaki', 'Mangá', 'Vol. 4', 'Editora JBC', NULL, 'Um parasita falha ao tomar o cérebro de Shinichi e se instala em sua mão direita. Obrigados a compartilhar o corpo, rapaz e criatura enfrentam outros invasores sem concordar sequer sobre o valor de uma vida humana. Edição brasileira da JBC, volume 4 (288 páginas; formato 15,0 x 21,0 cm; classificação indicativa: 16 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2025/07/parasyte-colorido-04-capa-p-150x210.jpg', 'https://editorajbc.com.br/mangas/colecao/parasyte-edicao-especial-colorida/vol/parasyte-edicao-especial-colorida-04/', '9786555948851', 'Ficção científica|Horror'),
    ('INK-3137', 'Sailor Moon Eternal Editon', 'Naoko Takeuchi', 'Mangá', 'Vol. 4', 'Editora JBC', NULL, 'Usagi descobre que pode se transformar em Sailor Moon. Reunir as demais guardiãs e proteger a Terra a aproxima de lembranças de outro reino que explicam por que a batalha chegou até ela. Edição brasileira da JBC, volume 4 (312 páginas; formato 15,2 × 21,0 cm; classificação indicativa: livre).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2026/01/sailor-moon-eternal-edition-04-capa-p-150x207.jpg', 'https://editorajbc.com.br/mangas/colecao/sailor-moon-eternal-editon/vol/sailor-moon-eternal-edition-04/', '9788545715603', 'Fantasia|Ação e aventura'),
    ('INK-3138', 'Saintia Shô', 'Chimaki Kuori', 'Mangá', 'Vol. 4', 'Editora JBC', NULL, 'Shoko entra em contato com as guerreiras que servem diretamente a Atena. A ameaça da deusa da discórdia transforma a procura pela irmã em uma batalha ligada ao destino do Santuário. Edição brasileira da JBC, volume 4 (184 páginas; formato 13,5 x 20,5 cm; classificação indicativa: 14 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2017/05/Saintia-Shô-04-Capa_p-150x228.jpg', 'https://editorajbc.com.br/mangas/colecao/saintia-sho/vol/saintia-sho-04/', '9788545702818', 'Ação e aventura|Fantasia'),
    ('INK-3139', 'Sangatsu no Lion - O Leão de Março', 'Chica Umino', 'Mangá', 'Vol. 4', 'Editora JBC', NULL, 'Rei Kiriyama joga shogi profissionalmente ainda adolescente e mora sozinho. As partidas revelam uma parte de sua história, enquanto a convivência com as irmãs Kawamoto abre espaço para uma vida além do tabuleiro. Edição brasileira da JBC, volume 4 (184 páginas; formato 13,2 × 20,0 cm; classificação indicativa: 16 anos).', 'https://editorajbc.com.br/wp-content/uploads/2023/06/sangatsu-04-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/sangatsu-no-lion/vol/sangatsu-no-lion-o-leao-de-marco-04/', '9786555944198', 'Slice of life|Drama'),
    ('INK-3140', 'Shaman King BIG', 'Hiroyuki Takei', 'Mangá', 'Vol. 4', 'Editora JBC', NULL, 'Yoh Asakura vê espíritos e luta ao lado do samurai Amidamaru. Para disputar o título de Shaman King, terá de compreender o que move os outros médiuns a buscar tamanho poder. Edição brasileira da JBC, volume 4 (384 páginas; formato 15,0 × 21,0 cm; classificação indicativa: 14 anos).', 'https://editorajbc.com.br/wp-content/uploads/2022/10/manga-shaman-king-big-04-capa-150x210.jpg', 'https://editorajbc.com.br/mangas/colecao/shaman-king-big/vol/shaman-king-big-04/', '9786555943368', 'Ação e aventura|Comédia'),
    ('INK-3141', 'Skip & Loafer', 'Misaki Takamatsu', 'Mangá', 'Vol. 4', 'Editora JBC', NULL, 'Mitsumi chega do interior para estudar em Tóquio com um plano de carreira detalhado. O primeiro dia já escapa do roteiro, e a amizade com Shima muda o que ela espera da escola e de si mesma. Edição brasileira da JBC, volume 4 (184 páginas; formato 12,8 × 18,2 cm; classificação indicativa: 12 anos).', 'https://editorajbc.com.br/wp-content/uploads/2025/03/skip-and-loafer-04-sobrecapa-150x210.jpg', 'https://editorajbc.com.br/mangas/colecao/skip-to-loafer/vol/skip-loafer-04/', '9786555948028', 'Drama'),
    ('INK-3142', 'Akane-Banashi', 'Yuki Suenaga e Takamasa Moue', 'Mangá', 'Vol. 5', 'Editora JBC', NULL, 'Akane quer conquistar seu lugar no rakugo, arte em que uma pessoa sentada diante da plateia interpreta todos os personagens de uma história. A expulsão do pai do meio profissional dá à sua ambição um motivo pessoal. Edição brasileira da JBC, volume 5 (208 páginas; formato 13,2 x 20,0 cm; classificação indicativa: 14 anos).', 'https://editorajbc.com.br/wp-content/uploads/2025/09/akane-banashi-05-capa-p-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/akane-banashi/vol/akane-banashi-05/', '9786555949629', 'Comédia|Drama'),
    ('INK-3143', 'Akira', 'Katsuhiro Otomo', 'Mangá', 'Vol. 5', 'Editora JBC', NULL, 'Em Neo-Tóquio, uma colisão durante uma corrida de motos põe Tetsuo sob custódia militar. Enquanto ele descobre um poder que mal consegue controlar, Kaneda acompanha o rastro de um segredo que a reconstrução da cidade tentou enterrar. Edição brasileira da JBC, volume 5 (416 páginas; formato 17,8 x 25,6 cm; classificação indicativa: 18 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2019/07/AKIRA-05-Sobrecapa_p-150x216.jpg', 'https://editorajbc.com.br/mangas/colecao/akira/vol/akira-05/', '9788545712367', 'Ficção científica'),
    ('INK-3144', 'Alice in Borderland', 'Haro Aso', 'Mangá', 'Vol. 5', 'Editora JBC', NULL, 'Arisu e os amigos encontram uma Tóquio estranhamente vazia. Para permanecer nela, precisam vencer jogos cujas cartas anunciam o tipo e a dificuldade da prova, mas escondem o preço de confiar na pessoa errada. Edição brasileira da JBC, volume 5 (336 páginas; formato 13,2 x 20,0 cm; classificação indicativa: 18 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2025/01/alice-in-borderland-big-05-capa-jon-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/alice-in-borderland/vol/alice-in-borderland-05/', '9786555947199', 'Ficção científica|Mistério e suspense'),
    ('INK-3145', 'Ao Ashi', 'Yugo Kobayashi', 'Mangá', 'Vol. 5', 'Editora JBC', NULL, 'Ashito Aoi chega ao futebol de base de Tóquio com instinto para ler o campo e pouca formação tática. Disputar espaço numa equipe profissional exige aprender a enxergar a jogada também pelos olhos dos companheiros. Edição brasileira da JBC, volume 5 (216 páginas; formato 13,2 × 20,0 cm; classificação indicativa: 14 anos).', 'https://editorajbc.com.br/wp-content/uploads/2023/12/manga-ao-ashi-05-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/ao-ashi/vol/ao-ashi-craques-da-bola-05/', '9786555945751', 'Esportes'),
    ('INK-3146', 'Astro Boy', 'Osamu Tezuka', 'Mangá', 'Vol. 5', 'Editora JBC', NULL, 'Atom é um menino robô com força extraordinária num mundo em que humanos constroem máquinas à própria imagem. Cada aventura coloca em questão o que seus criadores devem às criaturas que aprenderam a pensar e a sentir. Edição brasileira da JBC, volume 5 (416 páginas; formato 15,0 x 21,0 cm; classificação indicativa: 14 anos).', 'https://editorajbc.com.br/wp-content/uploads/2026/05/astro-boy-05-sobrecapa1-150x209.jpg', 'https://editorajbc.com.br/mangas/colecao/astro-boy/vol/astro-boy-big-05/', '9788545717102', 'Ação e aventura|Ficção científica'),
    ('INK-3147', 'Bakuman', 'Tsugumi Ohba e Takeshi Obata', 'Mangá', 'Vol. 5', 'Editora JBC', NULL, 'Moritaka Mashiro desenha e Akito Takagi escreve. Decididos a publicar juntos, os colegas descobrem a distância entre uma boa ideia e uma série capaz de sobreviver a reuniões editoriais, prazos semanais e votações de leitores. Edição brasileira da JBC, volume 5 (192 páginas; formato 13,5 x 20,5 cm; classificação indicativa: livre).', 'https://editorajbc.com.br/wp-content/uploads/2024/02/bakuman-05-capa-2024-150x228.jpg', 'https://editorajbc.com.br/mangas/colecao/bakuman/vol/bakuman-05-2/', '9786555946161', 'Comédia|Romance'),
    ('INK-3148', 'Blade - A Lâmina do Imortal - Nova Edição', 'Hiroaki Samura', 'Mangá', 'Vol. 5', 'Editora JBC', NULL, 'Rin procura os espadachins que destruíram sua família. Manji, um guerreiro cujos ferimentos se fecham sozinhos, aceita acompanhá-la. A jornada põe em dúvida quem decide qual morte merece vingança. Edição brasileira da JBC, volume 5 (440 páginas; formato 13,5 x 20,5 cm; classificação indicativa: 18 anos).', 'https://editorajbc.com.br/wp-content/uploads/2024/10/blade-05-capa-150x228.jpg', 'https://editorajbc.com.br/mangas/colecao/blade-a-lamina-do-imortal-nova-edicao/vol/blade-a-lamina-do-imortal-nova-edicao-05/', '9786555947113', 'Ação e aventura|Drama'),
    ('INK-3149', 'Blue Box', 'Kouji Miura', 'Mangá', 'Vol. 5', 'Editora JBC', NULL, 'Taiki chega cedo ao ginásio para treinar badminton e encontra Chinatsu, do basquete, praticando antes de todos. A convivência entre os atletas aproxima o primeiro amor da pressão por uma vaga nos campeonatos escolares. Edição brasileira da JBC, volume 5 (200 páginas; formato 13,2 x 20,0 cm; classificação indicativa: 10 anos).', 'https://editorajbc.com.br/wp-content/uploads/2025/07/blue-box-05-capa-p-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/blue-box/vol/blue-box-05/', '9786555948547', 'Romance|Esportes'),
    ('INK-3150', 'Blue Exorcist', 'Kazue Katō', 'Mangá', 'Vol. 5', 'Editora JBC', NULL, 'Rin Okumura descobre uma ligação de sangue com o mundo que os exorcistas combatem. Ele escolhe treinar ao lado deles, embora revelar a origem de suas chamas possa custar a confiança dos colegas. Edição brasileira da JBC, volume 5 (208 páginas; formato 13,5 x 20,0 cm; classificação indicativa: 14 anos).', 'https://editorajbc.com.br/wp-content/uploads/2025/07/blue-exorcist-05-capa-2025-p-150x228.jpg', 'https://editorajbc.com.br/mangas/colecao/blue-exorcist/vol/blue-exorcist-05-2/', '9786555949360', 'Ação e aventura|Drama|Fantasia'),
    ('INK-3151', 'Boa Noite Punpun', 'Inio Asano', 'Mangá', 'Vol. 5', 'Editora JBC', NULL, 'Punpun atravessa infância, adolescência e vida adulta representado como um pequeno pássaro num cenário realista. As promessas feitas a Aiko acompanham o personagem enquanto os adultos ao redor dele também perdem o rumo. Edição brasileira da JBC, volume 5 (448 páginas; formato 13,2 cm x 20 cm; classificação indicativa: 18 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2019/05/Boa-Noite-Punpun-05-Capa_p-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/boa-noite-punpun/vol/boa-noite-punpun-05/', '9788545711186', 'Drama'),
    ('INK-3152', 'CDZ - Next Dimension', 'Masami Kurumada', 'Mangá', 'Vol. 5', 'Editora JBC', NULL, 'Para tentar salvar Seiya, Atena e seus companheiros voltam ao tempo da guerra sagrada anterior. No Santuário de outra época, rostos desconhecidos ocupam as armaduras que os heróis julgavam conhecer. Edição brasileira da JBC, volume 5 (152 páginas; formato 13,5 x 20,0 cm; classificação indicativa: 14 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2016/02/capa_cdz_next_dimension_a_saga_de_hades_05_g-150x223.jpg', 'https://editorajbc.com.br/mangas/colecao/cdz-next-dimension/vol/cdz-next-dimension-a-saga-de-hades-05/', '9788577875535', 'Ação e aventura|Fantasia'),
    ('INK-3153', 'CDZ - The Lost Canvas Gaiden ESPECIAL', 'Masami Kurumada e Shiori Teshirogi', 'Mangá', 'Vol. 5', 'Editora JBC', NULL, 'As histórias acompanham os Cavaleiros de Ouro da geração de Lost Canvas em missões próprias. Longe do centro da guerra contra Hades, cada guerreiro revela o custo pessoal de proteger sua casa zodiacal. Edição brasileira da JBC, volume 5 (192 páginas; formato 13,2 x 20,0 cm; classificação indicativa: 14 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2023/02/lost-canvas-gaiden-05-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/cdz-the-lost-canvas-gaiden-esp/vol/cdz-the-lost-canvas-gaiden-esp-05/', '9788577876105', ''),
    ('INK-3154', 'CDZ Saint Seiya - Final Edition', 'Masami Kurumada', 'Mangá', 'Vol. 5', 'Editora JBC', NULL, 'Seiya conquista a Armadura de Pégaso e retorna ao Japão em busca da irmã. Seu caminho se cruza com o dos jovens cavaleiros que arriscam a vida para defender Atena. Edição brasileira da JBC, volume 5 (288 páginas; formato 13,2 × 20,0 cm; classificação indicativa: 14 anos).', 'https://editorajbc.com.br/wp-content/uploads/2025/09/cdz-final-edition-05-capa-p-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/saint-seiya-final-edition/vol/cavaleiros-do-zodiaco-saint-seiya-final-edition-05/', '9786555949667', 'Ação e aventura'),
    ('INK-3155', 'Cardcaptor Sakura Clear Card Arc', 'CLAMP', 'Mangá', 'Vol. 5', 'Editora JBC', NULL, 'Ao começar uma nova etapa na escola, Sakura percebe que as cartas que reuniu se tornaram transparentes. Sonhos enigmáticos e novos fenômenos mágicos levam a garota a investigar o que aconteceu com seus poderes. Edição brasileira da JBC, volume 5 (160 páginas; formato 13,2 x 20 cm; classificação indicativa: 10 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2020/10/cardcaptor-sakura-clear-card-arc-05-sobrecapa-150x228.jpg', 'https://editorajbc.com.br/mangas/colecao/cardcaptor-sakura-clear-card-arc/vol/cardcaptor-sakura-clear-card-arc-05/', '9788545713623', 'Fantasia'),
    ('INK-3156', 'Chi''s Sweet Home', 'Kanata Konami', 'Mangá', 'Vol. 5', 'Editora JBC', NULL, 'Uma gatinha se perde da mãe e encontra abrigo na casa da família Yamada. Do ponto de vista de Chi, uma porta fechada, a caixa de areia e a chegada de um visitante viram grandes acontecimentos. Edição brasileira da JBC, volume 5 (152 páginas; formato 17,0 x 24,0 cm; classificação indicativa: livre).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2022/04/chis-sweet-home-05-capa-p-150x209.jpg', 'https://editorajbc.com.br/mangas/colecao/chis-sweet-home/vol/chis-sweet-home-05/', '9786555942989', 'Comédia'),
    ('INK-3157', 'Final Fantasy - Lost Stranger', 'Hazuki Minase e Itsuki Kameya', 'Mangá', 'Vol. 5', 'Editora JBC', NULL, 'Dois irmãos são transportados para um mundo que reconhecem dos jogos de Final Fantasy. O conhecimento das regras parece uma vantagem até que uma perda torna urgente descobrir se a magia de ressurreição realmente existe. Edição brasileira da JBC, volume 5 (232 páginas; formato 13,2 x 20,0 cm; classificação indicativa: 14 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2023/06/manga-final-fantasy-lost-stranger-05-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/final-fantasy-lost-stranger/vol/final-fantasy-lost-stranger-05/', '9786555944686', 'Fantasia|Ficção científica'),
    ('INK-3158', 'Flying Witch', 'Chihiro Ishizuka', 'Mangá', 'Vol. 5', 'Editora JBC', NULL, 'Makoto vai morar com parentes no interior para se formar como bruxa. Entre a horta, a escola e as visitas de seres sobrenaturais, aprender magia também significa aprender os ritmos da nova casa. Edição brasileira da JBC, volume 5 (176 páginas; formato 13,2 × 20,0 cm; classificação indicativa: livre).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2024/04/flying-witch-05-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/flying-witch/vol/flying-witch-05/', '9786555946307', 'Fantasia|Comédia|Slice of life'),
    ('INK-3159', 'Fullmetal Alchemist ESPECIAL', 'Hiromu Arakawa', 'Mangá', 'Vol. 5', 'Editora JBC', NULL, 'Edward perdeu membros e Alphonse perdeu o corpo numa tentativa de trazer a mãe de volta pela alquimia. A procura por uma forma de reparar o erro leva os irmãos a laboratórios e quartéis onde a troca equivalente tem consequências humanas. Edição brasileira da JBC, volume 5 (200 páginas; formato 13,5 x 20,5 cm; classificação indicativa: 14 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2016/10/FMA-Esp_05_p-150x228.jpg', 'https://editorajbc.com.br/mangas/colecao/fullmetal-alchemist-especial/vol/fullmetal-alchemist-esp-05/', '9788545702351', 'Ação e aventura|Comédia|Drama|Fantasia|Ficção científica'),
    ('INK-3160', 'Fênix', 'Osamu Tezuka', 'Mangá', 'Vol. 5', 'Editora JBC', NULL, 'Osamu Tezuka alterna épocas remotas e futuros distantes para acompanhar pessoas que perseguem a ave de fogo. A promessa de vencer a morte expõe desejos que se repetem mesmo quando as civilizações desaparecem. Edição brasileira da JBC, volume 5 (592 páginas; formato 15,0 x 21,0 cm; classificação indicativa: 14 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2025/10/fenix-05-sobrecapa-p-150x210.jpg', 'https://editorajbc.com.br/mangas/colecao/fenix/vol/fenix-05/', '9786555949674', 'Drama|Fantasia'),
    ('INK-3161', 'Haikyu!!', 'Haruichi Furudate', 'Mangá', 'Vol. 5', 'Editora JBC', NULL, 'Hinata quer voar sobre a rede apesar da baixa estatura. Ao entrar no time de vôlei do Karasuno, precisa aprender a jogar com Kageyama, o levantador que antes o derrotou e que agora pode aproveitar melhor sua velocidade. Edição brasileira da JBC, volume 5 (384 páginas; formato 13,2 × 20,0 cm; classificação indicativa: livre).', 'https://editorajbc.com.br/wp-content/uploads/2022/11/manga-haikyu-05-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/haikyu/vol/haikyu-05/', '9786555943399', 'Esportes|Comédia|Drama'),
    ('INK-3162', 'Hellsing ESP.', 'Kouta Hirano', 'Mangá', 'Vol. 5', 'Editora JBC', NULL, 'A organização Hellsing protege a Inglaterra de ameaças sobrenaturais com a ajuda de Alucard, um vampiro a seu serviço. A policial Seras Victoria entra nesse mundo e precisa descobrir o que ainda significa agir como humana. Edição brasileira da JBC, volume 5 (208 páginas; formato 13,5 x 20,5 cm; classificação indicativa: 18 anos).', 'https://editorajbc.com.br/wp-content/uploads/2015/10/capa_hellsing_esp_05_g-150x228.jpg', 'https://editorajbc.com.br/mangas/colecao/hellsing-esp/vol/hellsing-especial-05/', '9788545715269', 'Ação e aventura'),
    ('INK-3163', 'InuYasha Wideban', 'Rumiko Takahashi', 'Mangá', 'Vol. 5', 'Editora JBC', NULL, 'Kagome atravessa um poço que liga sua casa ao Japão feudal. Ao lado de Inuyasha, procura os fragmentos de uma joia cobiçada por humanos e demônios, enquanto aprende a viver entre duas épocas. Edição brasileira da JBC, volume 5 (353 páginas; formato 12,8 x 18,2 cm; classificação indicativa: 14 anos).', 'https://editorajbc.com.br/wp-content/uploads/2022/10/manga-inuyasha-wideban-05-capa-150x213.jpg', 'https://editorajbc.com.br/mangas/colecao/inuyasha-wideban/vol/inuyasha-wideban-05/', '9786555943665', ''),
    ('INK-3164', 'Kamen Rider Kuuga BIG', 'Toshiki Inoue , Hitotsu Yokoshima e Shotaro Ishinomori', 'Mangá', 'Vol. 5', 'Editora JBC', NULL, 'O despertar de seres antigos transforma investigações policiais em uma corrida contra mortes inexplicáveis. Um poder ligado às ruínas dá a um jovem a capacidade de enfrentar os inimigos sob a forma de Kuuga. Edição brasileira da JBC, volume 5 (424 páginas; formato 13,2 × 20,0 cm; classificação indicativa: 16 anos).', 'https://editorajbc.com.br/wp-content/uploads/2023/03/manga-kamen-rider-kuuga-05-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/kamen-rider-kuuga-big/vol/kamen-rider-kuuga-big-05/', '9786555944365', 'Ação e aventura'),
    ('INK-3165', 'Medalist', 'Tsuruma Ikada', 'Mangá', 'Vol. 5', 'Editora JBC', NULL, 'Inori quer competir na patinação artística e encontra em Tsukasa um treinador disposto a apostar nela. Saltos e programas ganham peso numa modalidade em que começar tarde já é tratado como desvantagem. Edição brasileira da JBC, volume 5 (184 páginas; formato 13,2 × 20,0 cm; classificação indicativa: livre).', 'https://editorajbc.com.br/wp-content/uploads/2026/09/medalist-05-capa1-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/medalist/vol/medalist-05/', '9788545718734', 'Drama|Esportes'),
    ('INK-3166', 'My Home Hero', 'Naoki Yamakawa e Masashi Asaki', 'Mangá', 'Vol. 5', 'Editora JBC', NULL, 'Ao tentar proteger a filha de um relacionamento violento, um pai de família atrai a atenção do crime organizado. Seu repertório de romances policiais deixa de ser passatempo quando ele precisa sustentar a própria versão dos acontecimentos. Edição brasileira da JBC, volume 5 (200 páginas; formato 13,2 × 20,0 cm; classificação indicativa: 18 anos).', 'https://editorajbc.com.br/wp-content/uploads/2025/01/my-home-hero-05-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/my-home-hero/vol/my-home-hero-05/', '9786555947786', 'Drama|Mistério e suspense'),
    ('INK-3167', 'Nausicaä do Vale do Vento', 'Hayao Miyazaki', 'Mangá', 'Vol. 5', 'Editora JBC', NULL, 'Nausicaä explora uma floresta tóxica que avança sobre o território humano. Quando reinos vizinhos entram em guerra, compreender os insetos e o solo pode ser mais importante para o Vale do Vento do que vencer uma batalha. Edição brasileira da JBC, volume 5 (160 páginas; formato 18,2 x 25,6 cm; classificação indicativa: livre).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2024/12/nausicaa-05-capa-150x213.jpg', 'https://editorajbc.com.br/mangas/colecao/nausicaa-do-vale-do-vento/vol/nausicaa-do-vale-do-vento-05/', '9786555947892', 'Ação e aventura|Ficção científica'),
    ('INK-3168', 'Neon Genesis Evangelion - Edição de Colecionador', 'Yoshiyuki Sadamoto e Hideaki Anno', 'Mangá', 'Vol. 5', 'Editora JBC', NULL, 'Shinji é chamado pelo pai para pilotar uma unidade Evangelion contra os Anjos. A defesa da cidade depende de adolescentes que conhecem pouco das máquinas e ainda menos dos planos dos adultos que os comandam. Edição brasileira da JBC, volume 5 (352 páginas; formato 15,0 × 21,0 cm; classificação indicativa: 16 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2024/08/evangelion-05-capa-150x210.jpg', 'https://editorajbc.com.br/mangas/colecao/neon-genesis-evangelion-edicao-de-colecionador/vol/neon-genesis-evangelion-collectors-edition-05/', '9786555946994', 'Ação e aventura|Drama|Ficção científica'),
    ('INK-3169', 'Não Chame de Mistério', 'Yumi Tamura', 'Mangá', 'Vol. 5', 'Editora JBC', NULL, 'Totono percebe contradições que passam despercebidas por quem investiga um crime. Suas conversas longas e pouco convencionais desmontam tanto álibis quanto certezas sobre o comportamento das vítimas. Edição brasileira da JBC, volume 5 (200 páginas; formato 13,2 x 20,0 cm; classificação indicativa: 16 anos).', 'https://editorajbc.com.br/wp-content/uploads/2025/07/nao-chame-de-misterio-05-capa-p-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/nao-chame-de-misterio/vol/nao-chame-de-misterio-05/', '9786555948844', 'Ação e aventura|Comédia|Mistério e suspense'),
    ('INK-3170', 'Parasyte – Edição Especial Colorida', 'Hitoshi Iwaaki', 'Mangá', 'Vol. 5', 'Editora JBC', NULL, 'Um parasita falha ao tomar o cérebro de Shinichi e se instala em sua mão direita. Obrigados a compartilhar o corpo, rapaz e criatura enfrentam outros invasores sem concordar sequer sobre o valor de uma vida humana. Edição brasileira da JBC, volume 5 (296 páginas; formato 15,0 x 21,0 cm; classificação indicativa: 16 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2025/09/parasyte-colorido-05-capa-p-150x210.jpg', 'https://editorajbc.com.br/mangas/colecao/parasyte-edicao-especial-colorida/vol/parasyte-edicao-especial-colorida-05/', '9786555949735', 'Ficção científica|Horror'),
    ('INK-3171', 'Saintia Shô', 'Chimaki Kuori', 'Mangá', 'Vol. 5', 'Editora JBC', NULL, 'Shoko entra em contato com as guerreiras que servem diretamente a Atena. A ameaça da deusa da discórdia transforma a procura pela irmã em uma batalha ligada ao destino do Santuário. Edição brasileira da JBC, volume 5 (200 páginas; formato 13,5 x 20,5 cm; classificação indicativa: 14 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2017/07/Saintia-Shô-05-Capa_p-150x228.jpg', 'https://editorajbc.com.br/mangas/colecao/saintia-sho/vol/saintia-sho-05/', '9788545702900', 'Ação e aventura|Fantasia'),
    ('INK-3172', 'Sangatsu no Lion - O Leão de Março', 'Chica Umino', 'Mangá', 'Vol. 5', 'Editora JBC', NULL, 'Rei Kiriyama joga shogi profissionalmente ainda adolescente e mora sozinho. As partidas revelam uma parte de sua história, enquanto a convivência com as irmãs Kawamoto abre espaço para uma vida além do tabuleiro. Edição brasileira da JBC, volume 5 (184 páginas; formato 13,2 × 20,0 cm; classificação indicativa: 16 anos).', 'https://editorajbc.com.br/wp-content/uploads/2024/02/sangatsu-05-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/sangatsu-no-lion/vol/sangatsu-no-lion-o-leao-de-marco-05/', '9786555946048', 'Slice of life|Drama'),
    ('INK-3173', 'Shaman King BIG', 'Hiroyuki Takei', 'Mangá', 'Vol. 5', 'Editora JBC', NULL, 'Yoh Asakura vê espíritos e luta ao lado do samurai Amidamaru. Para disputar o título de Shaman King, terá de compreender o que move os outros médiuns a buscar tamanho poder. Edição brasileira da JBC, volume 5 (400 páginas; formato 15,0 × 21,0 cm; classificação indicativa: 14 anos).', 'https://editorajbc.com.br/wp-content/uploads/2023/02/manga-shaman-king-big-05-sobrecapa-150x210.jpg', 'https://editorajbc.com.br/mangas/colecao/shaman-king-big/vol/shaman-king-big-05/', '9786555943658', 'Ação e aventura|Comédia'),
    ('INK-3174', 'Skip & Loafer', 'Misaki Takamatsu', 'Mangá', 'Vol. 5', 'Editora JBC', NULL, 'Mitsumi chega do interior para estudar em Tóquio com um plano de carreira detalhado. O primeiro dia já escapa do roteiro, e a amizade com Shima muda o que ela espera da escola e de si mesma. Edição brasileira da JBC, volume 5 (184 páginas; formato 12,8 × 18,2 cm; classificação indicativa: 12 anos).', 'https://editorajbc.com.br/wp-content/uploads/2025/06/skip-and-loafer-05-capa-p-150x210.jpg', 'https://editorajbc.com.br/mangas/colecao/skip-to-loafer/vol/skip-loafer-05/', '9786555948875', 'Drama'),
    ('INK-3175', 'Akane-Banashi', 'Yuki Suenaga e Takamasa Moue', 'Mangá', 'Vol. 6', 'Editora JBC', NULL, 'Akane quer conquistar seu lugar no rakugo, arte em que uma pessoa sentada diante da plateia interpreta todos os personagens de uma história. A expulsão do pai do meio profissional dá à sua ambição um motivo pessoal. Edição brasileira da JBC, volume 6 (216 páginas; formato 13,2 x 20,0 cm; classificação indicativa: 14 anos).', 'https://editorajbc.com.br/wp-content/uploads/2025/10/akane-banashi-06-capa-p-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/akane-banashi/vol/akane-banashi-06/', '9786555949933', 'Comédia|Drama'),
    ('INK-3176', 'Akira', 'Katsuhiro Otomo', 'Mangá', 'Vol. 6', 'Editora JBC', NULL, 'Em Neo-Tóquio, uma colisão durante uma corrida de motos põe Tetsuo sob custódia militar. Enquanto ele descobre um poder que mal consegue controlar, Kaneda acompanha o rastro de um segredo que a reconstrução da cidade tentou enterrar. Edição brasileira da JBC, volume 6 (440 páginas; classificação indicativa: 18 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2019/11/AKIRA-06-Sobrecapa_p-150x216.jpg', 'https://editorajbc.com.br/mangas/colecao/akira/vol/akira-6/', '9788545712374', 'Ficção científica'),
    ('INK-3177', 'Alice in Borderland', 'Haro Aso', 'Mangá', 'Vol. 6', 'Editora JBC', NULL, 'Arisu e os amigos encontram uma Tóquio estranhamente vazia. Para permanecer nela, precisam vencer jogos cujas cartas anunciam o tipo e a dificuldade da prova, mas escondem o preço de confiar na pessoa errada. Edição brasileira da JBC, volume 6 (336 páginas; formato 13,2 x 20,0 cm; classificação indicativa: 18 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2025/09/alice-in-borderland-big-06-capa-p-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/alice-in-borderland/vol/alice-in-borderland-06/', '9786555948561', 'Ficção científica|Mistério e suspense'),
    ('INK-3178', 'Ao Ashi', 'Yugo Kobayashi', 'Mangá', 'Vol. 6', 'Editora JBC', NULL, 'Ashito Aoi chega ao futebol de base de Tóquio com instinto para ler o campo e pouca formação tática. Disputar espaço numa equipe profissional exige aprender a enxergar a jogada também pelos olhos dos companheiros. Edição brasileira da JBC, volume 6 (216 páginas; formato 13,2 × 20,0 cm; classificação indicativa: 14 anos).', 'https://editorajbc.com.br/wp-content/uploads/2024/02/ao-ashi-06-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/ao-ashi/vol/ao-ashi-craques-da-bola-06/', '9786555946116', 'Esportes'),
    ('INK-3179', 'Astro Boy', 'Osamu Tezuka', 'Mangá', 'Vol. 6', 'Editora JBC', NULL, 'Atom é um menino robô com força extraordinária num mundo em que humanos constroem máquinas à própria imagem. Cada aventura coloca em questão o que seus criadores devem às criaturas que aprenderam a pensar e a sentir. Edição brasileira da JBC, volume 6 (432 páginas; formato 15,0 x 21,0 cm; classificação indicativa: 14 anos).', 'https://editorajbc.com.br/wp-content/uploads/2026/09/ja18703-astro-boy-06-sobrecapa1-150x209.jpg', 'https://editorajbc.com.br/mangas/colecao/astro-boy/vol/astro-boy-big-06/', '9788545718703', 'Ação e aventura|Ficção científica'),
    ('INK-3180', 'Bakuman', 'Tsugumi Ohba e Takeshi Obata', 'Mangá', 'Vol. 6', 'Editora JBC', NULL, 'Moritaka Mashiro desenha e Akito Takagi escreve. Decididos a publicar juntos, os colegas descobrem a distância entre uma boa ideia e uma série capaz de sobreviver a reuniões editoriais, prazos semanais e votações de leitores. Edição brasileira da JBC, volume 6 (194 páginas; formato 13,5 x 20,5 cm; classificação indicativa: livre).', 'https://editorajbc.com.br/wp-content/uploads/2024/04/bakuman-06-capa-150x228.jpg', 'https://editorajbc.com.br/mangas/colecao/bakuman/vol/bakuman-06-2/', '9786555946383', 'Comédia|Romance'),
    ('INK-3181', 'Blade - A Lâmina do Imortal - Nova Edição', 'Hiroaki Samura', 'Mangá', 'Vol. 6', 'Editora JBC', NULL, 'Rin procura os espadachins que destruíram sua família. Manji, um guerreiro cujos ferimentos se fecham sozinhos, aceita acompanhá-la. A jornada põe em dúvida quem decide qual morte merece vingança. Edição brasileira da JBC, volume 6 (456 páginas; formato 13,5 x 20,5 cm; classificação indicativa: 18 anos).', 'https://editorajbc.com.br/wp-content/uploads/2025/01/blade-06-capa-rev-150x228.jpg', 'https://editorajbc.com.br/mangas/colecao/blade-a-lamina-do-imortal-nova-edicao/vol/blade-a-lamina-do-imortal-nova-edicao-06/', '9786555947526', 'Ação e aventura|Drama'),
    ('INK-3182', 'Blue Box', 'Kouji Miura', 'Mangá', 'Vol. 6', 'Editora JBC', NULL, 'Taiki chega cedo ao ginásio para treinar badminton e encontra Chinatsu, do basquete, praticando antes de todos. A convivência entre os atletas aproxima o primeiro amor da pressão por uma vaga nos campeonatos escolares. Edição brasileira da JBC, volume 6 (200 páginas; formato 13,2 x 20,0 cm; classificação indicativa: 10 anos).', 'https://editorajbc.com.br/wp-content/uploads/2025/09/blue-box-06-capa-p-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/blue-box/vol/blue-box-06/', '9786555949636', 'Romance|Esportes'),
    ('INK-3183', 'Blue Exorcist', 'Kazue Katō', 'Mangá', 'Vol. 6', 'Editora JBC', NULL, 'Rin Okumura descobre uma ligação de sangue com o mundo que os exorcistas combatem. Ele escolhe treinar ao lado deles, embora revelar a origem de suas chamas possa custar a confiança dos colegas. Edição brasileira da JBC, volume 6 (208 páginas; formato 13,5 x 20,5 cm; classificação indicativa: 14 anos).', 'https://editorajbc.com.br/wp-content/uploads/2013/12/capa_blue_exorcist_06_g-150x233.jpg', 'https://editorajbc.com.br/mangas/colecao/blue-exorcist/vol/blue-exorcist-06-2/', '9786555949582', 'Ação e aventura|Drama|Fantasia'),
    ('INK-3184', 'Boa Noite Punpun', 'Inio Asano', 'Mangá', 'Vol. 6', 'Editora JBC', NULL, 'Punpun atravessa infância, adolescência e vida adulta representado como um pequeno pássaro num cenário realista. As promessas feitas a Aiko acompanham o personagem enquanto os adultos ao redor dele também perdem o rumo. Edição brasileira da JBC, volume 6 (392 páginas; formato 13,2 cm x 20 cm; classificação indicativa: 18 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2019/05/Boa-Noite-Punpun-06-Capa_p-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/boa-noite-punpun/vol/boa-noite-punpun-06/', '9788545711193', 'Drama'),
    ('INK-3185', 'CDZ - Next Dimension', 'Masami Kurumada', 'Mangá', 'Vol. 6', 'Editora JBC', NULL, 'Para tentar salvar Seiya, Atena e seus companheiros voltam ao tempo da guerra sagrada anterior. No Santuário de outra época, rostos desconhecidos ocupam as armaduras que os heróis julgavam conhecer. Edição brasileira da JBC, volume 6 (152 páginas; formato 13,5 x 20,0 cm; classificação indicativa: 14 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2013/05/capa_cdz_next_dimension_a_saga_de_hades_06_g-150x223.jpg', 'https://editorajbc.com.br/mangas/colecao/cdz-next-dimension/vol/cdz-next-dimension-a-saga-de-hades-06/', '9788577876709', 'Ação e aventura|Fantasia'),
    ('INK-3186', 'CDZ - The Lost Canvas Gaiden ESPECIAL', 'Masami Kurumada e Shiori Teshirogi', 'Mangá', 'Vol. 6', 'Editora JBC', NULL, 'As histórias acompanham os Cavaleiros de Ouro da geração de Lost Canvas em missões próprias. Longe do centro da guerra contra Hades, cada guerreiro revela o custo pessoal de proteger sua casa zodiacal. Edição brasileira da JBC, volume 6 (200 páginas; formato 13,2 x 20,0 cm; classificação indicativa: 14 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2023/02/lost-canvas-gaiden-06-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/cdz-the-lost-canvas-gaiden-esp/vol/cdz-the-lost-canvas-gaiden-esp-06/', '9788577876723', ''),
    ('INK-3187', 'CDZ Saint Seiya - Final Edition', 'Masami Kurumada', 'Mangá', 'Vol. 6', 'Editora JBC', NULL, 'Seiya conquista a Armadura de Pégaso e retorna ao Japão em busca da irmã. Seu caminho se cruza com o dos jovens cavaleiros que arriscam a vida para defender Atena. Edição brasileira da JBC, volume 6 (296 páginas; formato 13,2 × 20,0 cm; classificação indicativa: 14 anos).', 'https://editorajbc.com.br/wp-content/uploads/2025/11/cdz-final-edition-06-capa-p-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/saint-seiya-final-edition/vol/cavaleiros-do-zodiaco-saint-seiya-final-edition-06/', '9788545715528', 'Ação e aventura'),
    ('INK-3188', 'Cardcaptor Sakura Clear Card Arc', 'CLAMP', 'Mangá', 'Vol. 6', 'Editora JBC', NULL, 'Ao começar uma nova etapa na escola, Sakura percebe que as cartas que reuniu se tornaram transparentes. Sonhos enigmáticos e novos fenômenos mágicos levam a garota a investigar o que aconteceu com seus poderes. Edição brasileira da JBC, volume 6 (160 páginas; formato 13,2 x 20 cm; classificação indicativa: 10 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2020/10/cardcaptor-sakura-clear-card-arc-06-sobrecapa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/cardcaptor-sakura-clear-card-arc/vol/cardcaptor-sakura-clear-card-arc-06/', '9788545713630', 'Fantasia'),
    ('INK-3189', 'Chi''s Sweet Home', 'Kanata Konami', 'Mangá', 'Vol. 6', 'Editora JBC', NULL, 'Uma gatinha se perde da mãe e encontra abrigo na casa da família Yamada. Do ponto de vista de Chi, uma porta fechada, a caixa de areia e a chegada de um visitante viram grandes acontecimentos. Edição brasileira da JBC, volume 6 (152 páginas; formato 17,0 x 24,0 cm; classificação indicativa: livre).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2022/08/manga-chis-sweet-home-06-capa-150x209.jpg', 'https://editorajbc.com.br/mangas/colecao/chis-sweet-home/vol/chis-sweet-home-06/', '9786555943276', 'Comédia'),
    ('INK-3190', 'Final Fantasy - Lost Stranger', 'Hazuki Minase e Itsuki Kameya', 'Mangá', 'Vol. 6', 'Editora JBC', NULL, 'Dois irmãos são transportados para um mundo que reconhecem dos jogos de Final Fantasy. O conhecimento das regras parece uma vantagem até que uma perda torna urgente descobrir se a magia de ressurreição realmente existe. Edição brasileira da JBC, volume 6 (232 páginas; formato 13,2 x 20,0 cm; classificação indicativa: 14 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2023/10/manga-finalfantasy-06-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/final-fantasy-lost-stranger/vol/final-fantasy-lost-stranger-06/', '9786555944822', 'Fantasia|Ficção científica'),
    ('INK-3191', 'Flying Witch', 'Chihiro Ishizuka', 'Mangá', 'Vol. 6', 'Editora JBC', NULL, 'Makoto vai morar com parentes no interior para se formar como bruxa. Entre a horta, a escola e as visitas de seres sobrenaturais, aprender magia também significa aprender os ritmos da nova casa. Edição brasileira da JBC, volume 6 (184 páginas; formato 13,2 × 20,0 cm; classificação indicativa: livre).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2024/06/flying-witch-06-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/flying-witch/vol/flying-witch-06/', '9786555946642', 'Fantasia|Comédia|Slice of life'),
    ('INK-3192', 'Fullmetal Alchemist ESPECIAL', 'Hiromu Arakawa', 'Mangá', 'Vol. 6', 'Editora JBC', NULL, 'Edward perdeu membros e Alphonse perdeu o corpo numa tentativa de trazer a mãe de volta pela alquimia. A procura por uma forma de reparar o erro leva os irmãos a laboratórios e quartéis onde a troca equivalente tem consequências humanas. Edição brasileira da JBC, volume 6 (192 páginas; formato 13,5 x 20,5 cm; classificação indicativa: 14 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2016/12/FMA-Esp_06_p-150x229.jpg', 'https://editorajbc.com.br/mangas/colecao/fullmetal-alchemist-especial/vol/fullmetal-alchemist-esp-06/', '9788545702542', 'Ação e aventura|Comédia|Drama|Fantasia|Ficção científica'),
    ('INK-3193', 'Fênix', 'Osamu Tezuka', 'Mangá', 'Vol. 6', 'Editora JBC', NULL, 'Osamu Tezuka alterna épocas remotas e futuros distantes para acompanhar pessoas que perseguem a ave de fogo. A promessa de vencer a morte expõe desejos que se repetem mesmo quando as civilizações desaparecem. Edição brasileira da JBC, volume 6 (664 páginas; formato 15,0 x 21,0 cm; classificação indicativa: 14 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2026/01/fenix-06-sobrecapa-p-150x210.jpg', 'https://editorajbc.com.br/mangas/colecao/fenix/vol/fenix-06/', '9788545716044', 'Drama|Fantasia'),
    ('INK-3194', 'Haikyu!!', 'Haruichi Furudate', 'Mangá', 'Vol. 6', 'Editora JBC', NULL, 'Hinata quer voar sobre a rede apesar da baixa estatura. Ao entrar no time de vôlei do Karasuno, precisa aprender a jogar com Kageyama, o levantador que antes o derrotou e que agora pode aproveitar melhor sua velocidade. Edição brasileira da JBC, volume 6 (400 páginas; formato 13,2 × 20,0 cm; classificação indicativa: livre).', 'https://editorajbc.com.br/wp-content/uploads/2023/03/haikyu-big-06-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/haikyu/vol/haikyu-06/', '9786555944099', 'Esportes|Comédia|Drama'),
    ('INK-3195', 'Hellsing ESP.', 'Kouta Hirano', 'Mangá', 'Vol. 6', 'Editora JBC', NULL, 'A organização Hellsing protege a Inglaterra de ameaças sobrenaturais com a ajuda de Alucard, um vampiro a seu serviço. A policial Seras Victoria entra nesse mundo e precisa descobrir o que ainda significa agir como humana. Edição brasileira da JBC, volume 6 (200 páginas; formato 13,5 x 20,5 cm; classificação indicativa: 18 anos).', 'https://editorajbc.com.br/wp-content/uploads/2015/11/capa_hellsing_esp_06_g-150x229.jpg', 'https://editorajbc.com.br/mangas/colecao/hellsing-esp/vol/hellsing-especial-06/', '9788545718048', 'Ação e aventura'),
    ('INK-3196', 'InuYasha Wideban', 'Rumiko Takahashi', 'Mangá', 'Vol. 6', 'Editora JBC', NULL, 'Kagome atravessa um poço que liga sua casa ao Japão feudal. Ao lado de Inuyasha, procura os fragmentos de uma joia cobiçada por humanos e demônios, enquanto aprende a viver entre duas épocas. Edição brasileira da JBC, volume 6 (353 páginas; formato 12,8 x 18,2 cm; classificação indicativa: 14 anos).', 'https://editorajbc.com.br/wp-content/uploads/2023/01/inuyasha-wideban-06-sobrecapa-p-150x213.jpg', 'https://editorajbc.com.br/mangas/colecao/inuyasha-wideban/vol/inuyasha-wideban-06/', '9786555944044', ''),
    ('INK-3197', 'Kamen Rider Kuuga BIG', 'Toshiki Inoue , Hitotsu Yokoshima e Shotaro Ishinomori', 'Mangá', 'Vol. 6', 'Editora JBC', NULL, 'O despertar de seres antigos transforma investigações policiais em uma corrida contra mortes inexplicáveis. Um poder ligado às ruínas dá a um jovem a capacidade de enfrentar os inimigos sob a forma de Kuuga. Edição brasileira da JBC, volume 6 (408 páginas; formato 13,2 × 20,0 cm; classificação indicativa: 16 anos).', 'https://editorajbc.com.br/wp-content/uploads/2023/07/manga-kamen-rider-kuuga-06-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/kamen-rider-kuuga-big/vol/kamen-rider-kuuga-big-06/', '9786555944815', 'Ação e aventura'),
    ('INK-3198', 'Medalist', 'Tsuruma Ikada', 'Mangá', 'Vol. 6', 'Editora JBC', NULL, 'Inori quer competir na patinação artística e encontra em Tsukasa um treinador disposto a apostar nela. Saltos e programas ganham peso numa modalidade em que começar tarde já é tratado como desvantagem. Edição brasileira da JBC, volume 6 (200 páginas; formato 13,2 × 20,0 cm; classificação indicativa: livre).', 'https://editorajbc.com.br/wp-content/uploads/2026/10/medalist-06-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/medalist/vol/medalist-06/', '9788545719397', 'Drama|Esportes'),
    ('INK-3199', 'My Home Hero', 'Naoki Yamakawa e Masashi Asaki', 'Mangá', 'Vol. 6', 'Editora JBC', NULL, 'Ao tentar proteger a filha de um relacionamento violento, um pai de família atrai a atenção do crime organizado. Seu repertório de romances policiais deixa de ser passatempo quando ele precisa sustentar a própria versão dos acontecimentos. Edição brasileira da JBC, volume 6 (200 páginas; formato 13,2 × 20,0 cm; classificação indicativa: 18 anos).', 'https://editorajbc.com.br/wp-content/uploads/2025/04/my-home-hero-06-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/my-home-hero/vol/my-home-hero-06/', '9786555948448', 'Drama|Mistério e suspense'),
    ('INK-3200', 'Nausicaä do Vale do Vento', 'Hayao Miyazaki', 'Mangá', 'Vol. 6', 'Editora JBC', NULL, 'Nausicaä explora uma floresta tóxica que avança sobre o território humano. Quando reinos vizinhos entram em guerra, compreender os insetos e o solo pode ser mais importante para o Vale do Vento do que vencer uma batalha. Edição brasileira da JBC, volume 6 (168 páginas; formato 18,2 x 25,6 cm; classificação indicativa: livre).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2025/10/nausicaa-06-capa-p-150x213.jpg', 'https://editorajbc.com.br/mangas/colecao/nausicaa-do-vale-do-vento/vol/nausicaa-do-vale-do-vento-06/', '9786555948455', 'Ação e aventura|Ficção científica'),
    ('INK-3201', 'Neon Genesis Evangelion - Edição de Colecionador', 'Yoshiyuki Sadamoto e Hideaki Anno', 'Mangá', 'Vol. 6', 'Editora JBC', NULL, 'Shinji é chamado pelo pai para pilotar uma unidade Evangelion contra os Anjos. A defesa da cidade depende de adolescentes que conhecem pouco das máquinas e ainda menos dos planos dos adultos que os comandam. Edição brasileira da JBC, volume 6 (352 páginas; formato 15,0 × 21,0 cm; classificação indicativa: 16 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2024/10/evangelion-06-capa-150x210.jpg', 'https://editorajbc.com.br/mangas/colecao/neon-genesis-evangelion-edicao-de-colecionador/vol/neon-genesis-evangelion-collectors-edition-06/', '9786555947472', 'Ação e aventura|Drama|Ficção científica'),
    ('INK-3202', 'Não Chame de Mistério', 'Yumi Tamura', 'Mangá', 'Vol. 6', 'Editora JBC', NULL, 'Totono percebe contradições que passam despercebidas por quem investiga um crime. Suas conversas longas e pouco convencionais desmontam tanto álibis quanto certezas sobre o comportamento das vítimas. Edição brasileira da JBC, volume 6 (200 páginas; formato 13,2 x 20,0 cm; classificação indicativa: 16 anos).', 'https://editorajbc.com.br/wp-content/uploads/2025/09/nao-chame-de-misterio-06-capa-p-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/nao-chame-de-misterio/vol/nao-chame-de-misterio-06/', '9786555949704', 'Ação e aventura|Comédia|Mistério e suspense'),
    ('INK-3203', 'Parasyte – Edição Especial Colorida', 'Hitoshi Iwaaki', 'Mangá', 'Vol. 6', 'Editora JBC', NULL, 'Um parasita falha ao tomar o cérebro de Shinichi e se instala em sua mão direita. Obrigados a compartilhar o corpo, rapaz e criatura enfrentam outros invasores sem concordar sequer sobre o valor de uma vida humana. Edição brasileira da JBC, volume 6 (296 páginas; formato 15,0 x 21,0 cm; classificação indicativa: 16 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2025/12/parasyte-colorido-06-capa-p-150x210.jpg', 'https://editorajbc.com.br/mangas/colecao/parasyte-edicao-especial-colorida/vol/parasyte-edicao-especial-colorida-06/', '9788545715597', 'Ficção científica|Horror'),
    ('INK-3204', 'Saintia Shô', 'Chimaki Kuori', 'Mangá', 'Vol. 6', 'Editora JBC', NULL, 'Shoko entra em contato com as guerreiras que servem diretamente a Atena. A ameaça da deusa da discórdia transforma a procura pela irmã em uma batalha ligada ao destino do Santuário. Edição brasileira da JBC, volume 6 (184 páginas; formato 13,5 x 20,5 cm; classificação indicativa: 14 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2017/09/Saintia-Shô-06-Capa_p-150x228.jpg', 'https://editorajbc.com.br/mangas/colecao/saintia-sho/vol/saintia-sho-06/', '9788545703228', 'Ação e aventura|Fantasia'),
    ('INK-3205', 'Sangatsu no Lion - O Leão de Março', 'Chica Umino', 'Mangá', 'Vol. 6', 'Editora JBC', NULL, 'Rei Kiriyama joga shogi profissionalmente ainda adolescente e mora sozinho. As partidas revelam uma parte de sua história, enquanto a convivência com as irmãs Kawamoto abre espaço para uma vida além do tabuleiro. Edição brasileira da JBC, volume 6 (184 páginas; formato 13,2 × 20,0 cm; classificação indicativa: 16 anos).', 'https://editorajbc.com.br/wp-content/uploads/2024/04/sangatsu-no-lion-06-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/sangatsu-no-lion/vol/sangatsu-no-lion-o-leao-de-marco-06/', '9786555946376', 'Slice of life|Drama'),
    ('INK-3206', 'Shaman King BIG', 'Hiroyuki Takei', 'Mangá', 'Vol. 6', 'Editora JBC', NULL, 'Yoh Asakura vê espíritos e luta ao lado do samurai Amidamaru. Para disputar o título de Shaman King, terá de compreender o que move os outros médiuns a buscar tamanho poder. Edição brasileira da JBC, volume 6 (376 páginas; formato 15,0 × 21,0 cm; classificação indicativa: 14 anos).', 'https://editorajbc.com.br/wp-content/uploads/2023/07/shaman-king-big-06-sobrecapa-150x210.jpg', 'https://editorajbc.com.br/mangas/colecao/shaman-king-big/vol/shaman-king-big-06/', '9786555944792', 'Ação e aventura|Comédia'),
    ('INK-3207', 'Skip & Loafer', 'Misaki Takamatsu', 'Mangá', 'Vol. 6', 'Editora JBC', NULL, 'Mitsumi chega do interior para estudar em Tóquio com um plano de carreira detalhado. O primeiro dia já escapa do roteiro, e a amizade com Shima muda o que ela espera da escola e de si mesma. Edição brasileira da JBC, volume 6 (184 páginas; formato 13,0 x 18,2 cm; classificação indicativa: 12 anos).', 'https://editorajbc.com.br/wp-content/uploads/2025/07/skip-and-loafer-06-capa-p-150x210.jpg', 'https://editorajbc.com.br/mangas/colecao/skip-to-loafer/vol/skip-loafer-06/', '9786555949490', 'Drama'),
    ('INK-3208', 'Akane-Banashi', 'Yuki Suenaga e Takamasa Moue', 'Mangá', 'Vol. 7', 'Editora JBC', NULL, 'Akane quer conquistar seu lugar no rakugo, arte em que uma pessoa sentada diante da plateia interpreta todos os personagens de uma história. A expulsão do pai do meio profissional dá à sua ambição um motivo pessoal. Edição brasileira da JBC, volume 7 (200 páginas; formato 13,2 x 20,0 cm; classificação indicativa: 14 anos).', 'https://editorajbc.com.br/wp-content/uploads/2026/01/akane-banashi-07-capa-p-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/akane-banashi/vol/akane-banashi-07/', '9788545715498', 'Comédia|Drama'),
    ('INK-3209', 'Alice in Borderland', 'Haro Aso', 'Mangá', 'Vol. 7', 'Editora JBC', NULL, 'Arisu e os amigos encontram uma Tóquio estranhamente vazia. Para permanecer nela, precisam vencer jogos cujas cartas anunciam o tipo e a dificuldade da prova, mas escondem o preço de confiar na pessoa errada. Edição brasileira da JBC, volume 7 (344 páginas; formato 13,2 x 20,0 cm; classificação indicativa: 18 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2025/12/alice-in-borderland-big-07-capa-p-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/alice-in-borderland/vol/alice-in-borderland-07/', '9788545715504', 'Ficção científica|Mistério e suspense'),
    ('INK-3210', 'Ao Ashi', 'Yugo Kobayashi', 'Mangá', 'Vol. 7', 'Editora JBC', NULL, 'Ashito Aoi chega ao futebol de base de Tóquio com instinto para ler o campo e pouca formação tática. Disputar espaço numa equipe profissional exige aprender a enxergar a jogada também pelos olhos dos companheiros. Edição brasileira da JBC, volume 7 (208 páginas; formato 13,2 × 20,0 cm; classificação indicativa: 14 anos).', 'https://editorajbc.com.br/wp-content/uploads/2024/04/ao-ashi-07-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/ao-ashi/vol/ao-ashi-craques-da-bola-07/', '9786555946345', 'Esportes'),
    ('INK-3211', 'Blade - A Lâmina do Imortal - Nova Edição', 'Hiroaki Samura', 'Mangá', 'Vol. 7', 'Editora JBC', NULL, 'Rin procura os espadachins que destruíram sua família. Manji, um guerreiro cujos ferimentos se fecham sozinhos, aceita acompanhá-la. A jornada põe em dúvida quem decide qual morte merece vingança. Edição brasileira da JBC, volume 7 (456 páginas; formato 13,5 x 20,5 cm; classificação indicativa: 18 anos).', 'https://editorajbc.com.br/wp-content/uploads/2025/06/blade-07-capa-p-150x228.jpg', 'https://editorajbc.com.br/mangas/colecao/blade-a-lamina-do-imortal-nova-edicao/vol/blade-a-lamina-do-imortal-nova-edicao-07/', '9786555948912', 'Ação e aventura|Drama'),
    ('INK-3212', 'Blue Box', 'Kouji Miura', 'Mangá', 'Vol. 7', 'Editora JBC', NULL, 'Taiki chega cedo ao ginásio para treinar badminton e encontra Chinatsu, do basquete, praticando antes de todos. A convivência entre os atletas aproxima o primeiro amor da pressão por uma vaga nos campeonatos escolares. Edição brasileira da JBC, volume 7 (200 páginas; formato 13,2 x 20,0 cm; classificação indicativa: 10 anos).', 'https://editorajbc.com.br/wp-content/uploads/2026/01/blue-box-07-capa-p-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/blue-box/vol/blue-box-07/', '9788545715511', 'Romance|Esportes'),
    ('INK-3213', 'Blue Exorcist', 'Kazue Katō', 'Mangá', 'Vol. 7', 'Editora JBC', NULL, 'Rin Okumura descobre uma ligação de sangue com o mundo que os exorcistas combatem. Ele escolhe treinar ao lado deles, embora revelar a origem de suas chamas possa custar a confiança dos colegas. Edição brasileira da JBC, volume 7 (192 páginas; formato 13,5 x 20,5 cm; classificação indicativa: 14 anos).', 'https://editorajbc.com.br/wp-content/uploads/2025/09/blueexorcist-07-capa-2025-p-150x228.jpg', 'https://editorajbc.com.br/mangas/colecao/blue-exorcist/vol/blue-exorcist-07-2/', '9786555949827', 'Ação e aventura|Drama|Fantasia'),
    ('INK-3214', 'Boa Noite Punpun', 'Inio Asano', 'Mangá', 'Vol. 7', 'Editora JBC', NULL, 'Punpun atravessa infância, adolescência e vida adulta representado como um pequeno pássaro num cenário realista. As promessas feitas a Aiko acompanham o personagem enquanto os adultos ao redor dele também perdem o rumo. Edição brasileira da JBC, volume 7 (376 páginas; formato 13,2 cm x 20 cm; classificação indicativa: 18 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2019/07/Boa-Noite-Punpun-07-Capa_p-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/boa-noite-punpun/vol/boa-noite-punpun-07/', '9788545712275', 'Drama'),
    ('INK-3215', 'CDZ - Next Dimension', 'Masami Kurumada', 'Mangá', 'Vol. 7', 'Editora JBC', NULL, 'Para tentar salvar Seiya, Atena e seus companheiros voltam ao tempo da guerra sagrada anterior. No Santuário de outra época, rostos desconhecidos ocupam as armaduras que os heróis julgavam conhecer. Edição brasileira da JBC, volume 7 (152 páginas; formato 13,5 x 20,0 cm; classificação indicativa: 14 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2014/03/capa_cdz_next_dimension_a_saga_de_hades_07_g-150x224.jpg', 'https://editorajbc.com.br/mangas/colecao/cdz-next-dimension/vol/cdz-next-dimension-a-saga-de-hades-07/', '9788577878031', 'Ação e aventura|Fantasia'),
    ('INK-3216', 'CDZ - The Lost Canvas Gaiden ESPECIAL', 'Masami Kurumada e Shiori Teshirogi', 'Mangá', 'Vol. 7', 'Editora JBC', NULL, 'As histórias acompanham os Cavaleiros de Ouro da geração de Lost Canvas em missões próprias. Longe do centro da guerra contra Hades, cada guerreiro revela o custo pessoal de proteger sua casa zodiacal. Edição brasileira da JBC, volume 7 (200 páginas; formato 13,2 x 20,0 cm; classificação indicativa: 14 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2023/03/lost-canvas-gaiden-07-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/cdz-the-lost-canvas-gaiden-esp/vol/cdz-the-lost-canvas-gaiden-esp-07/', '9788577877140', ''),
    ('INK-3217', 'CDZ Saint Seiya - Final Edition', 'Masami Kurumada', 'Mangá', 'Vol. 7', 'Editora JBC', NULL, 'Seiya conquista a Armadura de Pégaso e retorna ao Japão em busca da irmã. Seu caminho se cruza com o dos jovens cavaleiros que arriscam a vida para defender Atena. Edição brasileira da JBC, volume 7 (304 páginas; formato 13,2 × 20,0 cm; classificação indicativa: 14 anos).', 'https://editorajbc.com.br/wp-content/uploads/2025/12/cdz-final-edition-07-capa-p-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/saint-seiya-final-edition/vol/cavaleiros-do-zodiaco-saint-seiya-final-edition-07/', '9788545715917', 'Ação e aventura'),
    ('INK-3218', 'Cardcaptor Sakura Clear Card Arc', 'CLAMP', 'Mangá', 'Vol. 7', 'Editora JBC', NULL, 'Ao começar uma nova etapa na escola, Sakura percebe que as cartas que reuniu se tornaram transparentes. Sonhos enigmáticos e novos fenômenos mágicos levam a garota a investigar o que aconteceu com seus poderes. Edição brasileira da JBC, volume 7 (160 páginas; formato 13,2 × 20,0 cm; classificação indicativa: 10 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2021/03/cardcaptor-sakura-clear-card-arc-07-sobrecapa-p-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/cardcaptor-sakura-clear-card-arc/vol/cardcaptor-sakura-clear-card-arc-07/', '9786555940589', 'Fantasia'),
    ('INK-3219', 'Chi''s Sweet Home', 'Kanata Konami', 'Mangá', 'Vol. 7', 'Editora JBC', NULL, 'Uma gatinha se perde da mãe e encontra abrigo na casa da família Yamada. Do ponto de vista de Chi, uma porta fechada, a caixa de areia e a chegada de um visitante viram grandes acontecimentos. Edição brasileira da JBC, volume 7 (152 páginas; formato 17,0 x 24,0 cm; classificação indicativa: livre).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2023/02/manga-chis-sweet-home-07-capa-150x209.jpg', 'https://editorajbc.com.br/mangas/colecao/chis-sweet-home/vol/chis-sweet-home-07/', '9786555944228', 'Comédia'),
    ('INK-3220', 'Final Fantasy - Lost Stranger', 'Hazuki Minase e Itsuki Kameya', 'Mangá', 'Vol. 7', 'Editora JBC', NULL, 'Dois irmãos são transportados para um mundo que reconhecem dos jogos de Final Fantasy. O conhecimento das regras parece uma vantagem até que uma perda torna urgente descobrir se a magia de ressurreição realmente existe. Edição brasileira da JBC, volume 7 (248 páginas; formato 13,2 x 20,0 cm; classificação indicativa: 14 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2024/02/final-fantasy-ls7-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/final-fantasy-lost-stranger/vol/final-fantasy-lost-stranger-07/', '9786555946031', 'Fantasia|Ficção científica'),
    ('INK-3221', 'Flying Witch', 'Chihiro Ishizuka', 'Mangá', 'Vol. 7', 'Editora JBC', NULL, 'Makoto vai morar com parentes no interior para se formar como bruxa. Entre a horta, a escola e as visitas de seres sobrenaturais, aprender magia também significa aprender os ritmos da nova casa. Edição brasileira da JBC, volume 7 (184 páginas; formato 13,2 × 20,0 cm; classificação indicativa: livre).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2024/12/flying-witch-07-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/flying-witch/vol/flying-witch-07/', '9786555947403', 'Fantasia|Comédia|Slice of life'),
    ('INK-3222', 'Fullmetal Alchemist ESPECIAL', 'Hiromu Arakawa', 'Mangá', 'Vol. 7', 'Editora JBC', NULL, 'Edward perdeu membros e Alphonse perdeu o corpo numa tentativa de trazer a mãe de volta pela alquimia. A procura por uma forma de reparar o erro leva os irmãos a laboratórios e quartéis onde a troca equivalente tem consequências humanas. Edição brasileira da JBC, volume 7 (192 páginas; formato 13,5 x 20,5 cm; classificação indicativa: 14 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2017/01/FMA-Esp_07_p-150x229.jpg', 'https://editorajbc.com.br/mangas/colecao/fullmetal-alchemist-especial/vol/fullmetal-alchemist-esp-07/', '9788545702535', 'Ação e aventura|Comédia|Drama|Fantasia|Ficção científica'),
    ('INK-3223', 'Haikyu!!', 'Haruichi Furudate', 'Mangá', 'Vol. 7', 'Editora JBC', NULL, 'Hinata quer voar sobre a rede apesar da baixa estatura. Ao entrar no time de vôlei do Karasuno, precisa aprender a jogar com Kageyama, o levantador que antes o derrotou e que agora pode aproveitar melhor sua velocidade. Edição brasileira da JBC, volume 7 (408 páginas; formato 13,2 × 20,0 cm; classificação indicativa: livre).', 'https://editorajbc.com.br/wp-content/uploads/2023/08/manga-haikyu-07-capa-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/haikyu/vol/haikyu-07/', '9786555944624', 'Esportes|Comédia|Drama'),
    ('INK-3224', 'Hellsing ESP.', 'Kouta Hirano', 'Mangá', 'Vol. 7', 'Editora JBC', NULL, 'A organização Hellsing protege a Inglaterra de ameaças sobrenaturais com a ajuda de Alucard, um vampiro a seu serviço. A policial Seras Victoria entra nesse mundo e precisa descobrir o que ainda significa agir como humana. Edição brasileira da JBC, volume 7 (200 páginas; formato 13,5 x 20,5 cm; classificação indicativa: 18 anos).', 'https://editorajbc.com.br/wp-content/uploads/2016/01/capa_hellsing_esp_07_g-150x228.jpg', 'https://editorajbc.com.br/mangas/colecao/hellsing-esp/vol/hellsing-esp-07/', '9788545701163', 'Ação e aventura'),
    ('INK-3225', 'InuYasha Wideban', 'Rumiko Takahashi', 'Mangá', 'Vol. 7', 'Editora JBC', NULL, 'Kagome atravessa um poço que liga sua casa ao Japão feudal. Ao lado de Inuyasha, procura os fragmentos de uma joia cobiçada por humanos e demônios, enquanto aprende a viver entre duas épocas. Edição brasileira da JBC, volume 7 (353 páginas; formato 12,8 x 18,2 cm; classificação indicativa: 14 anos).', 'https://editorajbc.com.br/wp-content/uploads/2023/03/manga-inuyasha-wideban-07-capa-150x213.jpg', 'https://editorajbc.com.br/mangas/colecao/inuyasha-wideban/vol/inuyasha-wideban-07/', '9786555944433', ''),
    ('INK-3226', 'Kamen Rider Kuuga BIG', 'Toshiki Inoue , Hitotsu Yokoshima e Shotaro Ishinomori', 'Mangá', 'Vol. 7', 'Editora JBC', NULL, 'O despertar de seres antigos transforma investigações policiais em uma corrida contra mortes inexplicáveis. Um poder ligado às ruínas dá a um jovem a capacidade de enfrentar os inimigos sob a forma de Kuuga. Edição brasileira da JBC, volume 7 (400 páginas; formato 13,2 × 20,0 cm; classificação indicativa: 16 anos).', 'https://editorajbc.com.br/wp-content/uploads/2024/01/manga-kamen-rider-kuuga-07-capa-1-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/kamen-rider-kuuga-big/vol/kamen-rider-kuuga-big-07/', '9786555945805', 'Ação e aventura'),
    ('INK-3227', 'My Home Hero', 'Naoki Yamakawa e Masashi Asaki', 'Mangá', 'Vol. 7', 'Editora JBC', NULL, 'Ao tentar proteger a filha de um relacionamento violento, um pai de família atrai a atenção do crime organizado. Seu repertório de romances policiais deixa de ser passatempo quando ele precisa sustentar a própria versão dos acontecimentos. Edição brasileira da JBC, volume 7 (200 páginas; formato 13,2 × 20,0 cm; classificação indicativa: 18 anos).', 'https://editorajbc.com.br/wp-content/uploads/2025/12/my-home-hero-07-capa-p-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/my-home-hero/vol/my-home-hero-07/', '9788545715115', 'Drama|Mistério e suspense'),
    ('INK-3228', 'Nausicaä do Vale do Vento', 'Hayao Miyazaki', 'Mangá', 'Vol. 7', 'Editora JBC', NULL, 'Nausicaä explora uma floresta tóxica que avança sobre o território humano. Quando reinos vizinhos entram em guerra, compreender os insetos e o solo pode ser mais importante para o Vale do Vento do que vencer uma batalha. Edição brasileira da JBC, volume 7 (232 páginas; formato 18,2 x 25,6 cm; classificação indicativa: livre).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2025/11/nausicaa-07-capa-p-150x213.jpg', 'https://editorajbc.com.br/mangas/colecao/nausicaa-do-vale-do-vento/vol/nausicaa-do-vale-do-vento-07/', '9788545715733', 'Ação e aventura|Ficção científica'),
    ('INK-3229', 'Neon Genesis Evangelion - Edição de Colecionador', 'Yoshiyuki Sadamoto e Hideaki Anno', 'Mangá', 'Vol. 7', 'Editora JBC', NULL, 'Shinji é chamado pelo pai para pilotar uma unidade Evangelion contra os Anjos. A defesa da cidade depende de adolescentes que conhecem pouco das máquinas e ainda menos dos planos dos adultos que os comandam. Edição brasileira da JBC, volume 7 (384 páginas; formato 15,0 × 21,0 cm; classificação indicativa: 16 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2025/01/evangelion-07-capa-150x210.jpg', 'https://editorajbc.com.br/mangas/colecao/neon-genesis-evangelion-edicao-de-colecionador/vol/neon-genesis-evangelion-collectors-edition-07/', '9786555948004', 'Ação e aventura|Drama|Ficção científica'),
    ('INK-3230', 'Não Chame de Mistério', 'Yumi Tamura', 'Mangá', 'Vol. 7', 'Editora JBC', NULL, 'Totono percebe contradições que passam despercebidas por quem investiga um crime. Suas conversas longas e pouco convencionais desmontam tanto álibis quanto certezas sobre o comportamento das vítimas. Edição brasileira da JBC, volume 7 (200 páginas; formato 13,2 x 20,0 cm; classificação indicativa: 16 anos).', 'https://editorajbc.com.br/wp-content/uploads/2026/01/nao-chame-de-misterio-07-capa-p-150x227.jpg', 'https://editorajbc.com.br/mangas/colecao/nao-chame-de-misterio/vol/nao-chame-de-misterio-07/', '9788545715580', 'Ação e aventura|Comédia|Mistério e suspense'),
    ('INK-3231', 'Parasyte – Edição Especial Colorida', 'Hitoshi Iwaaki', 'Mangá', 'Vol. 7', 'Editora JBC', NULL, 'Um parasita falha ao tomar o cérebro de Shinichi e se instala em sua mão direita. Obrigados a compartilhar o corpo, rapaz e criatura enfrentam outros invasores sem concordar sequer sobre o valor de uma vida humana. Edição brasileira da JBC, volume 7 (280 páginas; formato 15,0 x 21,0 cm; classificação indicativa: 16 anos).', 'https://static-editorajbc.s3.amazonaws.com/wp-content/uploads/2026/03/parasyte-colorido-07-capa-150x210.jpg', 'https://editorajbc.com.br/mangas/colecao/parasyte-edicao-especial-colorida/vol/parasyte-edicao-especial-colorida-07/', '9788545716563', 'Ficção científica|Horror'),
